EXTRA_KC_BLUEPRINTS = {}

EXTRA_KC_BLUEPRINTS['WLAN_FREQ_CHANNEL'] = {'easy': [('Pada pita frekuensi 2.4 GHz standar Indonesia (ETSI), berapakah nomor tiga kanal standar yang benar-benar tidak saling bertumpuk (non-overlapping)?', {'A': 'Kanal 1, 6, dan 11', 'B': 'Kanal 1, 2, dan 3', 'C': 'Kanal 6, 7, dan 8', 'D': 'Kanal 2, 4, dan 6'}, 'A', 'COMBINATORIAL_REASONING', 'Pita 2.4 GHz memiliki lebar kanal 20-22 MHz dengan jarak pisah 5 MHz, sehingga hanya kanal 1, 6, dan 11 yang memiliki jarak 25 MHz bebas tumpang tindih.'), ('Berapakah jarak pemisah frekuensi minimal antar-pusat kanal pada pita 2.4 GHz agar dua Access Point yang bersebelahan tidak saling mengganggu?', {'A': '25 MHz (selisih minimal 5 nomor kanal)', 'B': '5 MHz (selisih 1 nomor kanal)', 'C': '10 MHz (selisih 2 nomor kanal)', 'D': '50 MHz (selisih 10 nomor kanal)'}, 'A', 'PROPORTIONAL_REASONING', 'Setiap kanal 802.11 b/g/n membutuhkan spektrum selebar 20-22 MHz. Dengan spasi kanal 5 MHz, diperlukan selisih 5 kanal (5 x 5 MHz = 25 MHz) agar terisolasi.'), ('Dalam pemasangan Access Point di lab TKJ, teknisi mengatur lebar kanal (channel bandwidth) dari 20 MHz menjadi 40 MHz pada pita 2.4 GHz. Variabel apakah yang dikorbankan demi mendapatkan kecepatan yang lebih tinggi?', {'A': 'Ketersediaan kanal non-overlapping berkurang drastis sehingga risiko interferensi antar-AP meningkat', 'B': 'Tegangan catu daya listrik adaptor AC harus dinaikkan dua kali lipat', 'C': 'Sandi WPA2 tidak lagi dapat digunakan oleh klien', 'D': 'Antena Access Point harus dipotong menjadi setengah panjang aslinya'}, 'A', 'CONTROLLING_VARIABLES', 'Kanal 40 MHz pada 2.4 GHz menghabiskan lebih dari 8 nomor kanal sekaligus, menyisakan ruang spektrum yang sangat sempit dan memicu interferensi hebat dengan AP tetangga.'), ('Mengapa pita frekuensi 5 GHz menyediakan jumlah kanal non-overlapping yang jauh lebih banyak (hingga 24+ kanal) dibanding pita 2.4 GHz?', {'A': 'Karena spektrum total pita 5 GHz jauh lebih lebar dan setiap kanal dialokasikan spasi 20 MHz tanpa tumpang tindih', 'B': 'Karena gelombang 5 GHz bergerak lebih lambat di udara dibanding 2.4 GHz', 'C': 'Karena pita 5 GHz tidak menggunakan gelombang elektromagnetik radio', 'D': 'Karena pemerintah membebaskan seluruh regulasi daya transmisi untuk 5 GHz'}, 'A', 'CORRELATIONAL_REASONING', 'Rentang spektrum 5 GHz (UNII-1, UNII-2, UNII-3) mencakup ratusan MHz spektrum bersih dengan kanal mandiri berjarak 20 MHz, tidak seperti 2.4 GHz yang hanya selebar ~80 MHz.'), ('Jika tiga Access Point di tiga kelas berdampingan semuanya disetel secara default pada kanal 6, apa dampak probabilistik yang paling mungkin dialami siswa saat ujian online?', {'A': 'Peluang terjadinya Co-Channel Interference (CCI) melonjak tinggi sehingga throughput turun akibat stasiun harus saling mengantre giliran', 'B': 'Sinyal radio otomatis saling meniadakan hingga bernilai 0 dBm di semua kelas', 'C': 'Alamat IP laptop siswa otomatis tertukar satu sama lain', 'D': 'Kapasitas kecepatan data ketiga Access Point berlipat ganda tiga kali lipat'}, 'A', 'PROBABILISTIC_REASONING', 'Pada kanal yang sama (CCI), seluruh perangkat berbagi satu media transmisi half-duplex; probabilitas stasiun mendeteksi media sibuk meningkat tajam, memicu delay antrean.')], 'medium': [('Seorang teknisi mengamati bahwa AP Lab A berada di kanal 1, sedangkan AP Lab B disetel di kanal 2. Fenomena interferensi apakah yang terjadi di antara kedua AP tersebut?', {'A': 'Adjacent Channel Interference (ACI) yang merusak paket data akibat tumpang tindih spektrum samping tanpa koordinasi CSMA/CA', 'B': 'Co-Channel Interference murni yang dapat dikoordinasikan secara teratur oleh mekanisme CSMA/CA', 'C': 'Multipath fading yang menguatkan sinyal kedua lab', 'D': 'Cross-talk kabel UTP pada rak server'}, 'A', 'CORRELATIONAL_REASONING', 'ACI terjadi ketika dua kanal parsial saling bertumpuk (kanal 1 dan 2); radio tidak dapat mendekode sinyal tetangga sebagai frame Wi-Fi yang sah melainkan menganggapnya sebagai derau liar perusak frame.'), ('Di sebuah lorong sekolah terdapat 4 unit Access Point berjajar (AP-1, AP-2, AP-3, AP-4). Susunan alokasi kanal 2.4 GHz manakah yang paling ideal untuk meminimalkan interferensi antar-sel yang bersebelahan?', {'A': 'AP-1: Kanal 1, AP-2: Kanal 6, AP-3: Kanal 11, AP-4: Kanal 1', 'B': 'AP-1: Kanal 1, AP-2: Kanal 2, AP-3: Kanal 3, AP-4: Kanal 4', 'C': 'AP-1: Kanal 6, AP-2: Kanal 6, AP-3: Kanal 6, AP-4: Kanal 6', 'D': 'AP-1: Kanal 11, AP-2: Kanal 10, AP-3: Kanal 9, AP-4: Kanal 8'}, 'A', 'COMBINATORIAL_REASONING', 'Pola pengulangan kanal (frequency reuse) 1-6-11-1 memberikan jarak fisik terjauh antara dua AP yang menggunakan kanal sama (AP-1 dan AP-4), meminimalkan CCI dan mengeliminasi ACI.'), ('Access Point disetel pada pita 5 GHz dengan kanal bonding 80 MHz. Jika teknisi menurunkan lebar kanal menjadi 20 MHz pada daya pancar yang sama, perubahan proporsional apakah yang terjadi pada tingkat noise floor dan sensitivitas penerima?', {'A': 'Noise floor turun sekitar 6 dB sehingga sensitivitas dan jangkauan sinyal efektif meningkat', 'B': 'Noise floor naik dua kali lipat sehingga throughput bertambah cepat', 'C': 'Sensitivitas penerima anjlok total hingga sinyal tidak terdeteksi', 'D': 'Kecepatan maksimal modulasi MCS otomatis terkunci di tingkat terendah'}, 'A', 'PROPORTIONAL_REASONING', 'Daya derau termal (noise) berbanding lurus dengan lebar pita (kTB). Mempersempit lebar kanal dari 80 MHz ke 20 MHz (faktor 4x) memangkas noise floor sebesar 10*log10(4) = 6 dB, meningkatkan SNR pada jarak jauh.'), ('Kelompok kanal pada pita frekuensi 5 GHz yang masuk dalam regulasi Dynamic Frequency Selection (DFS) diwajibkan oleh regulasi telekomunikasi untuk...', {'A': 'Secara otomatis mendeteksi pulsa radar cuaca/militer dan segera memindahkan kanal operasinya jika radar terdeteksi', 'B': 'Membatasi kecepatan transmisi maksimal menjadi 11 Mbps saja', 'C': 'Mengharuskan pengguna membayar lisensi bulanan ke operator seluler', 'D': 'Mematikan fungsi enkripsi sandi saat malam hari'}, 'A', 'CONTROLLING_VARIABLES', 'Kanal DFS (UNII-2 dan UNII-2 Extended: kanal 52-144) berbagi spektrum dengan sistem radar penerbangan dan cuaca; AP wajib melakukan Channel Availability Check (CAC) dan pindah kanal jika mendeteksi radar.'), ('Dalam pengujian koneksi Wi-Fi di area kantin sekolah yang ramai dengan 5 SSID berbeda pada kanal 1, probabilitas sebuah paket data mengalami collision dan retransmisi meningkat karena...', {'A': 'Banyaknya frame beacon dari masing-masing AP yang menghabiskan airtime serta stasiun yang saling berebut slot transmisi', 'B': 'Kabel serat optik ISP mengalami pemanasan berlebih akibat gelombang microwave', 'C': 'Sistem operasi ponsel memblokir otomatis seluruh koneksi pada kanal bernomor ganjil', 'D': 'Alamat IP gateway terbagi habis ke seluruh stasiun sekitar'}, 'A', 'PROBABILISTIC_REASONING', 'Semakin banyak AP dan stasiun pada kanal yang sama, semakin besar probabilitas slot backoff acak yang dipilih bertabrakan, ditambah beban overhead frame manajemen (beacon) yang memakan kapasitas airtime.')], 'hard': [('Sebuah gedung sekolah berlantai dua memiliki 6 ruangan kelas yang saling bersinggungan secara vertikal dan horizontal. Rencana alokasi kanal 2.4 GHz manakah yang meminimalkan interferensi 3 dimensi?', {'A': 'Lantai 1: [R1: Ch 1, R2: Ch 6, R3: Ch 11]; Lantai 2: [R4: Ch 6, R5: Ch 11, R6: Ch 1] sehingga tidak ada kanal sama yang berposisi tepat vertikal', 'B': 'Lantai 1: [Ch 1, Ch 1, Ch 1]; Lantai 2: [Ch 6, Ch 6, Ch 6]', 'C': 'Lantai 1 dan Lantai 2 seluruhnya menggunakan kanal 6', 'D': 'Lantai 1: [Ch 1, Ch 2, Ch 3]; Lantai 2: [Ch 4, Ch 5, Ch 6]'}, 'A', 'COMBINATORIAL_REASONING', 'Perencanaan sel 3 dimensi wajib memperhitungkan propagasi sinyal menembus lantai beton; memastikan ruang atas dan bawah menggunakan kanal berbeda mencegah degradasi CCI vertikal.'), ('Di titik tengah antara AP-1 (kanal 6, sinyal -65 dBm) dan AP-2 (kanal 6, sinyal -70 dBm), berapakah Signal-to-Interference Ratio (SIR) yang diterima klien laptop dari AP-1?', {'A': '+5 dB', 'B': '-135 dB', 'C': '+135 dB', 'D': '0 dB'}, 'A', 'PROPORTIONAL_REASONING', 'Rasio sinyal terhadap interferensi (SIR) dalam skala desibel dihitung dari selisih daya: SIR = P_sinyal - P_interferensi = (-65 dBm) - (-70 dBm) = +5 dB. Nilai ini di bawah ambang aman (biasanya butuh >= 10-15 dB untuk modulasi tinggi).'), ('Seorang administrator jaringan ingin membuktikan apakah kanal 20 MHz lebih tahan interferensi dibanding kanal 40 MHz pada area padat. Prosedur kontrol variabel manakah yang paling valid?', {'A': 'Mengukur persentase packet loss pada AP yang sama di lokasi tetap dengan beban trafik klien identik, saat disetel 20 MHz vs 40 MHz', 'B': 'Menguji 20 MHz di dalam lab komputer lalu menguji 40 MHz di lapangan terbuka', 'C': 'Menguji 20 MHz menggunakan smartphone bermerek X lalu menguji 40 MHz menggunakan laptop bermerek Y', 'D': 'Mengubah lebar kanal sekaligus mematikan koneksi internet ISP'}, 'A', 'CONTROLLING_VARIABLES', 'Untuk mengisolasi pengaruh lebar kanal, lokasi fisik, perangkat klien, jarak, dan kondisi interferensi latar belakang wajib dijaga konstan.'), ('Hasil tangkapan spectrum analyzer menunjukkan adanya lonjakan energi elektromagnetik kontinu non-802.11 selebar 20 MHz di sekitar frekuensi 2445-2465 MHz. Sumber interferensi apakah yang paling mungkin menyebabkan fenomena ini?', {'A': 'Perangkat oven microwave atau kamera CCTV analog nirkabel 2.4 GHz di dekat laboratorium', 'B': 'Kabel serat optik yang tertekuk di kotak OTB', 'C': 'Koneksi kabel UTP Cat 6 yang dipasang berdekatan dengan saklar lampu', 'D': 'Server DNS sekolah yang kelebihan beban permintaan kueri'}, 'A', 'CORRELATIONAL_REASONING', 'Microwave oven dan pemancar video analog bekerja pada frekuensi sekitar 2.45 GHz tanpa protokol CSMA/CA, memancarkan gelombang kontinu (duty cycle tinggi) yang melumpuhkan kanal 6-10.'), ('Jika kanal radio mengalami utilisasi rata-rata sebesar 85% akibat transmisi video streaming dari lab sebelah, probabilitas sebuah klien baru berhasil mendapatkan slot transmisi pada upaya backoff pertama adalah...', {'A': 'Sangat rendah (< 15%) karena stasiun harus berulang kali menunda transmisi akibat saluran terdeteksi sibuk', 'B': 'Tepat 50% karena peluang selalu acak biner', 'C': 'Mendekati 100% karena protokol Wi-Fi memprioritaskan klien baru', 'D': '0% permanen hingga Access Point di-restart ulang'}, 'A', 'PROBABILISTIC_REASONING', 'Pada utilisasi kanal 85%, probabilitas saluran berada dalam kondisi IDLE hanya 15%. Peluang klien menemukan kanal bebas tanpa menunda transmisi sangat kecil, memicu penumpukan antrean.')]}

EXTRA_KC_BLUEPRINTS['WLAN_SECURITY_AUTH'] = {'easy': [('Mengapa protokol keamanan lawas Wired Equivalent Privacy (WEP) sudah dinyatakan tidak aman dan dilarang digunakan pada jaringan sekolah?', {'A': 'Algoritma enkripsi RC4 dan Initialization Vector (IV) yang pendek (24-bit) mudah dipecahkan dalam hitungan menit', 'B': 'WEP hanya dapat bekerja pada kabel serat optik', 'C': 'WEP membatasi kecepatan data maksimal hanya 1 Kbps', 'D': 'WEP mewajibkan penggunaan server biometrik sidik jari'}, 'A', 'CONTROLLING_VARIABLES', 'WEP memiliki cacat kriptografi fatal pada implementasi RC4 dan daur ulang IV 24-bit yang memungkinkan kunci enkripsi direkonstruksi dengan menangkap paket data.'), ('Perbedaan mendasar antara metode pengamanan WPA2-Personal (PSK) dan WPA2-Enterprise terletak pada...', {'A': 'WPA2-Personal menggunakan satu kata sandi bersama (PSK), sedangkan WPA2-Enterprise menggunakan autentikasi unik per pengguna melalui server RADIUS/802.1X', 'B': 'WPA2-Enterprise tidak memerlukan Access Point', 'C': 'WPA2-Personal hanya dapat diakses oleh komputer bersistem operasi Linux', 'D': 'WPA2-Enterprise membatasi jangkauan sinyal hanya sejauh 2 meter'}, 'A', 'COMBINATORIAL_REASONING', 'WPA2-Personal mengandalkan Pre-Shared Key yang dibagikan ke semua orang, sedangkan WPA2-Enterprise memisahkan identitas tiap siswa/guru menggunakan server autentikasi terpusat (802.1X/RADIUS).'), ('Berapakah batas minimal panjang karakter kata sandi (passphrase) yang diwajibkan oleh standar keamanan WPA2-Personal (PSK)?', {'A': '8 karakter', 'B': '4 karakter', 'C': '16 karakter', 'D': '32 karakter'}, 'A', 'PROPORTIONAL_REASONING', 'Standar IEEE 802.11i menetapkan panjang passphrase WPA2-PSK antara 8 hingga 63 karakter ASCII (atau 64 digit heksadesimal).'), ('Algoritma penyandian simetris modern yang wajib diimplementasikan pada standar pengamanan WPA2 untuk menjamin kerahasiaan payload data adalah...', {'A': 'Advanced Encryption Standard (AES) dengan mode CCMP', 'B': 'Data Encryption Standard (DES) 56-bit', 'C': 'MD5 Hash Algorithm', 'D': 'Caesar Cipher 3-shift'}, 'A', 'CONTROLLING_VARIABLES', 'WPA2 mewajibkan penggunaan cipher blok AES-CCMP (Counter Mode with Cipher Block Chaining Message Authentication Code Protocol) menggantikan TKIP dan WEP.'), ('Berapa banyakkah ruang kombinasi kunci yang harus diuji penyerang dalam serangan brute force terhadap sandi Wi-Fi 8 digit yang hanya menggunakan angka (0-9)?', {'A': '100.000.000 kemungkinan (10^8)', 'B': '80 kemungkinan (10 x 8)', 'C': '256 kemungkinan (2^8)', 'D': '40.320 kemungkinan (8!)'}, 'A', 'PROBABILISTIC_REASONING', 'Dengan 10 kemungkinan angka untuk tiap posisi pada panjang 8 digit, total ruang kunci adalah 10^8 = 100 juta kombinasi, yang dapat diuji dalam hitungan detik oleh kartu grafis modern.')], 'medium': [('Pada proses asosiasi klien ke AP dengan WPA2-PSK, celah keamanan apakah yang dimanfaatkan penyerang saat menangkap paket 4-Way Handshake (EAPOL)?', {'A': 'Penyerang dapat membawa data handshake tersebut untuk melakukan offline dictionary attack tanpa terdeteksi oleh jaringan', 'B': 'Penyerang dapat langsung melihat kata sandi dalam bentuk teks polos (plaintext)', 'C': 'Penyerang dapat membakar sirkuit radio Access Point dari jarak jauh', 'D': 'Penyerang dapat mengubah IP gateway menjadi IP publik'}, 'A', 'CORRELATIONAL_REASONING', 'Frame EAPOL 4-Way Handshake berisi nilai nonce dan MIC yang dihitung dari PMK. Penyerang dapat menguji jutaan kata kamus secara offline di komputernya sendiri tanpa mengirim paket ke AP.'), ('Keunggulan utama protokol Simultaneous Authentication of Equals (SAE) pada standar WPA3 dibandingkan WPA2-PSK dalam melindungi kata sandi sekolah adalah...', {'A': 'Tahan terhadap serangan offline dictionary attack dan menyediakan fitur forward secrecy meskipun kata sandi berhasil dipecahkan di masa depan', 'B': 'Membuat sinyal radio dapat menembus plat timbal tebal', 'C': 'Menghilangkan kebutuhan konfigurasi SSID pada Access Point', 'D': 'Otomatis memberikan kuota internet tanpa batas pada setiap klien'}, 'A', 'CONTROLLING_VARIABLES', 'WPA3-SAE (Dragonfly Handshake) menggunakan pertukaran kunci berbasis kurva eliptik yang mengharuskan interaksi aktif, menggagalkan analisis kamus pasif offline.'), ('Dalam implementasi WPA2-Enterprise di SMK, protokol EAP manakah yang paling umum digunakan karena mendukung enkripsi terowongan TLS menggunakan sertifikat server tanpa mewajibkan sertifikat pada tiap smartphone siswa?', {'A': 'PEAP-MSCHAPv2 (Protected EAP)', 'B': 'EAP-MD5', 'C': 'LEAP (Lightweight EAP)', 'D': 'PAP Tanpa Enkripsi'}, 'A', 'COMBINATORIAL_REASONING', 'PEAP membangun terowongan terenkripsi TLS menggunakan sertifikat digital server RADIUS terlebih dahulu, lalu mengalirkan autentikasi username/password siswa secara aman di dalam terowongan.'), ('Jika panjang kata sandi nirkabel bertambah dari 8 karakter menjadi 12 karakter alfanumerik (62 variasi karakter), faktor peningkatan ruang kunci yang harus dipecahkan penyerang meningkat secara proporsional sebesar...', {'A': '62^4 kali lipat lebih banyak', 'B': '4 kali lipat lebih banyak', 'C': '48 kali lipat lebih banyak', 'D': 'Tetap sama karena hash selalu berukuran 256-bit'}, 'A', 'PROPORTIONAL_REASONING', 'Ruang kunci eksponensial terhadap panjang sandi: 62^12 / 62^8 = 62^(12-8) = 62^4 = 14.776.336 kali lipat lebih banyak, membuat serangan brute-force menjadi tidak praktis secara komputasi.'), ('Ketika Access Point diaktifkan dalam mode transisi (WPA2/WPA3 Mixed Mode) demi mendukung laptop siswa versi lama, risiko keamanan apakah yang meningkat secara probabilistik?', {'A': 'Penyerang dapat memalsukan frame deauthentication untuk memaksa klien melakukan downgrade attack ke protokol WPA2 yang lebih rentan', 'B': 'Access Point akan mengalami korsleting listrik', 'C': 'Ponsel siswa akan terhapus seluruh datanya', 'D': 'Kecepatan internet seluruh sekolah turun menjadi 0 bps'}, 'A', 'PROBABILISTIC_REASONING', 'Mode transisi memungkinkan penyerang mengirim paket deauth dan memalsukan beacon untuk memperdaya klien agar menganggap AP hanya mendukung WPA2, sehingga membuka celah dictionary attack.')], 'hard': [('Serangan Evil Twin / Rogue AP dilakukan dengan membuat AP palsu dengan SSID dan BSSID identik di dekat sekolah. Protokol keamanan manakah yang kebal terhadap serangan penyadapan kredensial ini?', {'A': 'WPA2/WPA3-Enterprise EAP-TLS dengan validasi sertifikat CA digital pada perangkat klien', 'B': 'WPA2-PSK dengan kata sandi 63 karakter', 'C': 'Jaringan terbuka (Open) dengan autentikasi Captive Portal web', 'D': 'WEP 128-bit dengan kunci heksadesimal statis'}, 'A', 'CONTROLLING_VARIABLES', 'Pada EAP-TLS, klien memverifikasi keaslian sertifikat digital server RADIUS resmi sekolah; jika AP penyerang mencoba memalsukan identitas, validasi sertifikat gagal dan klien menolak asosiasi.'), ('Sebuah cluster GPU penguji dapat mengkalkulasi 1.000.000 hash PBKDF2 per detik. Berapa lama waktu maksimal yang dibutuhkan untuk menguji seluruh kombinasi kata sandi numerik 8 digit (10^8 kombinasi)?', {'A': '100 detik (kurang dari 2 menit)', 'B': '10.000 detik', 'C': '100 hari', 'D': '1 tahun'}, 'A', 'PROPORTIONAL_REASONING', 'Waktu = Total Kombinasi / Kecepatan = 10^8 / 10^6 = 100 detik. Hal ini membuktikan bahwa kata sandi Wi-Fi 8 digit numerik sangat rapuh dan dapat ditembus dalam waktu kurang dari dua menit.'), ('Fitur Protected Management Frames (IEEE 802.11w / PMF) yang wajib pada WPA3 berfungsi melindungi jaringan dari serangan...', {'A': 'Deauthentication Flood Attack dan Disassociation DoS liar yang memutus koneksi klien secara paksa', 'B': 'Pencurian kabel antena fisik di atap gedung', 'C': 'Penyelundupan virus melalui flashdisk siswa', 'D': 'Penurunan tegangan listrik dari PLN'}, 'A', 'CORRELATIONAL_REASONING', 'Pada 802.11 standar, frame manajemen (seperti deauth) tidak dienkripsi sehingga mudah dipalsukan penyerang; 802.11w menambahkan kriptografi integrity protection pada frame manajemen unicast dan broadcast.'), ('Pada arsitektur WPA2, Group Temporal Key (GTK) diperbarui secara berkala (rekey interval) oleh Access Point. Tujuan utama pembaharuan kunci kelompok ini adalah...', {'A': 'Mencegah mantan siswa yang telah meninggalkan jaringan untuk mendekripsi lalu lintas data siaran (broadcast/multicast) berikutnya', 'B': 'Mengganti nama SSID secara acak setiap 1 jam', 'C': 'Mematikan koneksi internet pada komputer guru', 'D': 'Menghapus riwayat browsing web siswa di cache browser'}, 'A', 'CONTROLLING_VARIABLES', 'GTK digunakan bersama untuk mendekripsi frame broadcast/multicast; jika GTK tidak diperbarui saat klien terputus, mantan klien tetap dapat menyadap frame siaran di udara.'), ('Mengapa fitur Wi-Fi Protected Setup (WPS) metode PIN 8 digit sangat rentan terhadap serangan Pixie Dust / Reaver?', {'A': 'Karena verifikasi PIN dibagi menjadi dua blok terpisah (4 digit dan 3 digit + checksum) sehingga penyerang hanya perlu menguji 10^4 + 10^3 = 11.000 percobaan', 'B': "Karena PIN WPS selalu bernilai '00000000' pada semua perangkat", 'C': 'Karena WPS mengirimkan kunci rahasia melalui gelombang inframerah', 'D': 'Karena WPS menonaktifkan seluruh antena AP saat tombol ditekan'}, 'A', 'PROBABILISTIC_REASONING', 'Protokol WPS memiliki kelemahan desain di mana AP memvalidasi 4 digit pertama dan 3 digit terakhir secara terpisah; probabilitas menemukan PIN melonjak drastis dari 1 banding 100 juta menjadi hanya 11.000 percobaan.')]}

EXTRA_KC_BLUEPRINTS['WLAN_HOST_HARDENING'] = {'easy': [('Fitur pada Access Point yang membatasi perangkat klien nirkabel agar hanya dapat berkomunikasi ke gateway internet dan dilarang saling berkirim data antarsesama klien disebut...', {'A': 'Client Isolation (AP Isolation)', 'B': 'Port Forwarding', 'C': 'Bridge Multipath', 'D': 'DHCP Relay'}, 'A', 'CONTROLLING_VARIABLES', 'Client Isolation memblokir lalu lintas data peer-to-peer layer 2 antarklien pada satu SSID, melindungi perangkat siswa dari serangan sniffing dan infeksi malware sesama pengguna.'), ('Langkah pertama dan paling mendasar yang wajib dilakukan teknisi saat mengonfigurasi Access Point baru untuk mencegah pengambilalihan kontrol oleh pihak luar adalah...', {'A': "Mengganti nama pengguna dan kata sandi default pabrikan (seperti 'admin/admin')", 'B': 'Mengecat casing luar Access Point dengan warna gelap', 'C': 'Memotong kabel daya antena', 'D': 'Menonaktifkan lampu indikator LED'}, 'A', 'CONTROLLING_VARIABLES', 'Kredensial bawaan pabrik terdokumentasi secara publik di internet; membiarkan kredensial default memungkinkan siapa pun di jaringan nirkabel masuk ke menu konfigurasi AP.'), ('Metode pengamanan di mana administrator mendaftarkan alamat perangkat keras fisik komputer yang diizinkan terhubung ke Access Point dinamakan...', {'A': 'MAC Address Filtering (Whitelist)', 'B': 'IP Subnetting', 'C': 'DNS Filtering', 'D': 'WPA Handshake'}, 'A', 'COMBINATORIAL_REASONING', 'MAC Filtering membandingkan alamat fisik NIC klien dengan daftar akses (whitelist/blacklist) sebelum mengizinkan asosiasi jaringan.'), ('Protokol manajemen antarmuka grafis web (Web UI) yang aman dan terenkripsi untuk mengelola konfigurasi Access Point dari browser adalah...', {'A': 'HTTPS (Port 443)', 'B': 'HTTP Polos (Port 80)', 'C': 'Telnet (Port 23)', 'D': 'TFTP (Port 69)'}, 'A', 'CONTROLLING_VARIABLES', 'HTTPS menggunakan enkripsi TLS untuk melindungi pengiriman nama pengguna dan kata sandi manajemen agar tidak tersadap dalam teks polos di jaringan lokal.'), ('Mengapa metode pengamanan MAC Address Filtering dinilai tidak memadai sebagai satu-satunya lapisan pertahanan jaringan nirkabel?', {'A': 'Karena alamat MAC ditransmisikan tanpa enkripsi pada header frame nirkabel dan sangat mudah dipalsukan (MAC Spoofing)', 'B': 'Karena alamat MAC otomatis berganti setiap 5 menit pada semua kartu jaringan', 'C': 'Karena alamat MAC hanya dimiliki oleh router dan bukan oleh laptop siswa', 'D': 'Karena tabel MAC filtering membatasi jumlah pengguna maksimal hanya 2 komputer'}, 'A', 'PROBABILISTIC_REASONING', 'Header 802.11 selalu memuat MAC address secara terbuka di udara; penyerang dengan paket sniffer dapat melihat MAC klien sah lalu memprogram kartu Wi-Fi miliknya untuk meniru MAC tersebut.')], 'medium': [('Mengapa menyembunyikan nama SSID (Hidden SSID / Disable SSID Broadcast) tidak memberikan perlindungan keamanan yang nyata terhadap peretas?', {'A': 'Karena SSID tetap terpancar jelas dalam frame Probe Request dan Probe Response saat ada klien sah yang hendak terhubung', 'B': 'Karena kabel UTP akan memancarkan cahaya yang memperlihatkan nama SSID', 'C': 'Karena Access Point akan mati otomatis jika SSID disembunyikan', 'D': 'Karena laptop siswa akan otomatis menampilkan pesan peringatan ke kepala sekolah'}, 'A', 'CORRELATIONAL_REASONING', 'Menonaktifkan beacon broadcast hanya menyembunyikan SSID dari daftar Wi-Fi pengguna awam; penyerang yang menjalankan sniffer seperti Kismet/Airodump dapat membaca nama SSID saat pertukaran probe frame terjadi.'), ('Pada router gateway MikroTik lab sekolah, aturan Firewall Filter manakah yang tepat untuk memblokir akses manajemen Winbox (port 8291) dari segmen nirkabel siswa (wlan1)?', {'A': '/ip firewall filter add chain=input in-interface=wlan1 protocol=tcp dst-port=8291 action=drop', 'B': '/ip firewall filter add chain=forward in-interface=wlan1 action=accept', 'C': '/ip firewall nat add chain=srcnat action=masquerade', 'D': '/ip route add gateway=192.168.1.1'}, 'A', 'COMBINATORIAL_REASONING', "Trafik yang ditujukan langsung ke router gateway diproses pada rantai 'input'; aturan drop pada antarmuka wlan1 dengan tujuan port 8291 memastikan siswa tidak dapat mengakses panel Winbox."), ('Administrator jaringan menerapkan pembatasan bandwidth (Simple Queue) sebesar 2 Mbps per siswa. Jika kapasitas total internet sekolah adalah 20 Mbps, berapa jumlah siswa maksimal yang dapat streaming bersamaan pada kapasitas puncak tanpa buffering?', {'A': '10 siswa (20 Mbps / 2 Mbps)', 'B': '40 siswa', 'C': '5 siswa', 'D': '100 siswa'}, 'A', 'PROPORTIONAL_REASONING', 'Perhitungan alokasi proporsional sederhana: Total Bandwidth / Alokasi per Klien = 20 Mbps / 2 Mbps = 10 stasiun aktif simultan pada batas jaminan bandwidth (CIR).'), ('Tindakan pengerasan (hardening) layanan pada Access Point enterprise mencakup penonaktifan service yang tidak aman dan tidak diperlukan. Layanan manakah yang wajib dimatikan?', {'A': 'Telnet, FTP polos, dan Universal Plug and Play (UPnP)', 'B': 'SSH dan HTTPS', 'C': 'Antarmuka Radio 5 GHz', 'D': 'Sistem Enkripsi WPA2/WPA3'}, 'A', 'CONTROLLING_VARIABLES', 'Telnet dan FTP mengirim kredensial tanpa enkripsi, sedangkan UPnP memiliki banyak kerentanan eksekusi perintah jarak jauh; mematikannya mereduksi bidang serangan (attack surface).'), ('Jika Client Isolation dinonaktifkan pada jaringan Wi-Fi publik sekolah, probabilitas penyebaran worm/malware antar-laptop di ruang lab meningkat karena...', {'A': 'Perangkat yang terinfeksi dapat memindai port dan mengeksploitasi kerentanan SMB/RPC pada komputer lain di subnet yang sama secara langsung', 'B': 'Server ISP akan memutuskan bandwidth internasional', 'C': 'Kabel grounding saklar akan menghasilkan tegangan listrik tinggi', 'D': 'Antena Access Point akan kehilangan daya pancar secara permanen'}, 'A', 'PROBABILISTIC_REASONING', 'Tanpa isolasi klien, setiap host di subnet yang sama memiliki visibilitas layer 2 penuh; malware dapat menyebar otomatis melalui exploit protokol jaringan lokal (seperti port SMB 445).')], 'hard': [('Untuk memisahkan akses jaringan guru dan siswa pada satu Access Point fisik yang sama, teknik arsitektur jaringan yang paling aman dan efisien adalah...', {'A': 'Membuat Multi-SSID dengan pemetaan masing-masing SSID ke tag VLAN 802.1Q yang berbeda menuju saklar distribusi', 'B': 'Membuat dua kata sandi yang sama persis pada satu SSID', 'C': 'Memasang dua adaptor daya listrik pada satu Access Point', 'D': 'Menempelkan isolasi fisik pada separuh antena AP'}, 'A', 'COMBINATORIAL_REASONING', 'Multi-SSID yang dipetakan ke VLAN terpisah (misal SSID Guru -> VLAN 10, SSID Siswa -> VLAN 20) mengisolasi broadcast domain dan jalur data secara logis pada switch Layer 2/3.'), ('Pada tabel Firewall MikroTik, aturan penolakan paket rusak `/ip firewall filter add chain=input connection-state=invalid action=drop` ditempatkan di urutan paling atas. Dampak positifnya terhadap kinerja router adalah...', {'A': 'Mereduksi beban CPU secara signifikan karena paket sampah/invalid langsung dibuang tanpa perlu dievaluasi oleh ratusan aturan firewall di bawahnya', 'B': 'Menaikkan kecepatan transmisi radio sebesar 200%', 'C': 'Mengubah alamat IP statis siswa menjadi dinamis', 'D': 'Menghapus kebutuhan kabel tanah pembumian'}, 'A', 'CORRELATIONAL_REASONING', 'Korelasi urutan aturan firewall: mengevaluasi koneksi invalid dan menolaknya di awal mencegah pemborosan siklus komputasi prosesor pada paket anomali atau serangan scanning.'), ('Serangan Rogue DHCP Server terjadi ketika laptop siswa menjalankan DHCP server liar yang membagikan IP gateway palsu ke siswa lain. Fitur keamanan saklar kabel yang bertugas memitigasi serangan ini adalah...', {'A': "DHCP Snooping dengan menyetel port uplink router sebagai 'trusted' dan port AP/klien sebagai 'untrusted'", 'B': 'Spanning Tree Protocol (STP)', 'C': 'Link Aggregation (LACP)', 'D': 'Port Mirroring'}, 'A', 'CONTROLLING_VARIABLES', "DHCP Snooping memvalidasi pesan DHCP; paket balasan DHCP Offer dari port 'untrusted' (port siswa/AP liar) langsung diblokir oleh switch sehingga klien hanya menerima IP dari server resmi."), ('Administrator menggunakan Per Connection Queue (PCQ) MikroTik dengan parameter pcq-rate=0 (pembagian rata dinamis). Jika bandwidth total 30 Mbps dibagi untuk 15 pengguna aktif, berapakah bandwidth yang didapat masing-masing pengguna?', {'A': '2 Mbps (30 Mbps / 15 pengguna)', 'B': '15 Mbps', 'C': '30 Mbps penuh untuk tiap pengguna', 'D': '0.5 Mbps'}, 'A', 'PROPORTIONAL_REASONING', 'PCQ secara proporsional dan matematis membagi total bandwidth secara adil dan merata ke seluruh sub-antrean aktif: 30 Mbps / 15 = 2 Mbps per stasiun.'), ('Sistem Wireless Intrusion Prevention System (WIPS) memantau pola frame 802.11. Jika terdeteksi lebih dari 50 frame Deauthentication per detik dari BSSID yang tidak dikenal, tindakan otomatis berbasis probabilitas ancaman yang diambil adalah...', {'A': 'Memicu alarm intrusi penyerangan Deauth DoS dan mengaktifkan containment untuk mengisolasi stasiun penyerang', 'B': 'Memformat ulang harddisk seluruh laptop di laboratorium', 'C': 'Menonaktifkan koneksi listrik ke seluruh gedung', 'D': 'Mengubah seluruh enkripsi jaringan menjadi teks polos'}, 'A', 'PROBABILISTIC_REASONING', 'Lonjakan tajam frame deauth (>50 fps) mengindikasikan serangan DoS aktif (probabilitas tinggi serangan brute/jamming); WIPS merespons dengan memblokir MAC penyerang pada sistem kontrol terpusat.')]}

EXTRA_KC_BLUEPRINTS['WLAN_SIGNAL_PROP'] = {'easy': [('Satuan standar internasional yang digunakan untuk mengukur kekuatan sinyal radio nirkabel yang diterima antena smartphone (RSSI) adalah...', {'A': 'dBm (desibel miliwatt)', 'B': 'Volt (tegangan listrik)', 'C': 'Watt per detik', 'D': 'Ohm (hambatan)'}, 'A', 'CONTROLLING_VARIABLES', 'RSSI dinyatakan dalam satuan logaritmik dBm (desibel relatif terhadap 1 miliwatt) untuk merepresentasikan rentang daya radio yang sangat lebar secara praktis.'), ('Mengapa nilai kekuatan sinyal Wi-Fi -55 dBm jauh lebih kuat dan lebih stabil dibandingkan nilai sinyal -85 dBm pada penerima ponsel siswa?', {'A': 'Karena skala dBm bernilai negatif, sehingga angka yang lebih mendekati nol mewakili daya elektromagnetik yang lebih besar', 'B': 'Karena angka 85 lebih besar dari 55 pada bilangan bulat biasa', 'C': 'Karena nilai -85 dBm menandakan frekuensi radio bekerja pada kecepatan 85 GHz', 'D': 'Karena -55 dBm menunjukkan bahwa ponsel berada di luar jangkauan menara pemancar'}, 'A', 'PROPORTIONAL_REASONING', 'Dalam skala logaritmik negatif dBm, -55 dBm memiliki daya sekitar 3.16 picowatt, sedangkan -85 dBm hanya sekitar 0.00316 picowatt (daya -55 dBm adalah 1.000 kali lebih besar dibanding -85 dBm).'), ('Pola radiasi pancaran gelombang elektromagnetik dari antena jenis omnidirectional pada Access Point ruangan lab memancarkan energi dengan bentuk...', {'A': 'Melingkar 360 derajat pada bidang horizontal (menyerupai bentuk donat/toroid)', 'B': 'Garis lurus terpusat satu arah seperti sinar laser tajam', 'C': 'Kerucut sempit 10 derajat ke arah langit-langit', 'D': 'Pola kotak kubus beraturan'}, 'A', 'CONTROLLING_VARIABLES', 'Antena omnidirectional menyebarkan sinyal sama kuat ke segala arah horizontal (360 derajat) namun memiliki sudut pancar terbatas pada bidang vertikal.'), ('Urutan material partisi penghalang ruangan dari yang menyebabkan nilai redaman (attenuation loss) paling kecil hingga paling besar terhadap sinyal Wi-Fi adalah...', {'A': 'Kaca jendela bening < Dinding partisi gypsum < Dinding batu bata merah < Tembok beton bertulang tebal', 'B': 'Tembok beton bertulang < Batu bata merah < Gypsum < Kaca jendela', 'C': 'Plat besi baja < Kaca bening < Gypsum < Kayu triplek', 'D': 'Dinding bata merah < Plat timbal < Kaca jendela < Udara hampa'}, 'A', 'COMBINATORIAL_REASONING', 'Bahan ringan tak berpori seperti kaca dan gypsum hanya meredam 2-4 dB, batu bata meredam 6-10 dB, sedangkan beton bertulang tebal meredam lebih dari 15-20 dB.'), ('Seorang siswa berjalan perlahan menjauhi Access Point di lorong sekolah dari jarak 2 meter ke 10 meter. Hubungan korelasional apakah yang teramati pada indikator RSSI di perangkatnya?', {'A': 'Kekuatan sinyal berkorelasi negatif terhadap jarak (nilai dBm semakin negatif seiring bertambahnya jarak)', 'B': 'Kekuatan sinyal tidak dipengaruhi oleh jarak di udara terbuka', 'C': 'Semakin jauh jarak, sinyal radio justru semakin bertambah kuat secara linier', 'D': 'Jarak menyebabkan frekuensi Access Point otomatis berubah dari 2.4 GHz ke 60 GHz'}, 'A', 'CORRELATIONAL_REASONING', 'Korelasi negatif antara jarak dan RSSI terjadi akibat penyebaran energi gelombang elektromagnetik di ruang bebas (Free Space Path Loss).')], 'medium': [('Berdasarkan rumus Free Space Path Loss (FSPL), jika jarak antara laptop siswa dan Access Point digandakan dari 4 meter menjadi 8 meter (2 kali lipat), berapakah perkiraan penurunan daya sinyal yang diterima?', {'A': 'Daya sinyal berkurang sekitar 6 dB (menjadi 1/4 dari daya semula)', 'B': 'Daya sinyal berkurang tepat 2 dB', 'C': 'Daya sinyal berkurang setengahnya (3 dB)', 'D': 'Daya sinyal berkurang 20 dB'}, 'A', 'PROPORTIONAL_REASONING', 'Sesuai hukum kuadrat terbalik (inverse-square law): $20 \\log_{10}(2) \\approx 6.02\\text{ dB}$. Menggandakan jarak menyebabkan pelemahan 6 dB atau kerapatan daya turun menjadi 1/4.'), ('Mengapa sinyal Wi-Fi pada frekuensi 2.4 GHz mampu menembus dinding ruangan kelas lab lebih baik daripada frekuensi 5 GHz?', {'A': 'Frekuensi 2.4 GHz memiliki panjang gelombang lebih panjang (~12.5 cm) sehingga mengalami redaman absorpsi material yang lebih rendah', 'B': 'Frekuensi 5 GHz tidak dapat merambat melalui udara', 'C': 'Pita 2.4 GHz memiliki kecepatan rambat cahaya lebih tinggi daripada 5 GHz', 'D': 'Pemerintah melarang sinyal 5 GHz memantul pada benda padat'}, 'A', 'CONTROLLING_VARIABLES', 'Panjang gelombang 2.4 GHz (~12.5 cm) dua kali lebih panjang dari 5 GHz (~6 cm). Gelombang berfrekuensi lebih tinggi lebih mudah diserap dan dihamburkan oleh molekul material padat.'), ('Pada instalasi jaringan nirkabel Point-to-Point antargedung sekolah sejauh 200 meter, mengapa pohon rindang di tengah jalur harus dipangkas meskipun garis lurus penglihatan (Line of Sight) masih terlihat jelas?', {'A': 'Karena dedaunan pohon menghalangi area Zona Fresnel Pertama (First Fresnel Zone) yang menyebabkan interferensi destruktif akibat difraksi sinyal', 'B': 'Karena pohon menyerap seluruh sinyal internet melalui akar tanaman', 'C': 'Karena pohon memancarkan gelombang inframerah yang membingungkan AP', 'D': 'Karena sinyal Wi-Fi hanya dapat merambat jika pohon dicat putih'}, 'A', 'CORRELATIONAL_REASONING', 'Transmisi gelombang mikro membutuhkan ruang bebas hambatan setidaknya 60% dari radius Zona Fresnel Pertama; obstruksi pada area elipsoid ini memicu redaman difraksi hebat.'), ('Sebuah Access Point luar ruangan memiliki daya pancar (Tx Power) 20 dBm dan dihubungkan ke antena pengarah dengan gain 14 dBi melalui kabel pigtail dengan redaman 2 dB. Berapakah nilai Equivalent Isotropically Radiated Power (EIRP)?', {'A': '32 dBm (20 dBm - 2 dB + 14 dBi)', 'B': '36 dBm', 'C': '8 dBm', 'D': '280 dBm'}, 'A', 'COMBINATORIAL_REASONING', 'EIRP = Tx Power (dBm) - Cable Loss (dB) + Antenna Gain (dBi) = 20 - 2 + 14 = 32 dBm (setara dengan sekitar 1.58 Watt daya radiasi efektif isotropis).'), ('Ketika 30 siswa bergerak dan berjalan di dalam ruang laboratorium nirkabel, sinyal RSSI pada smartphone penguji mengalami fluktuasi acak naik-turun sebesar 5-8 dB. Fenomena propagasi apakah yang terjadi?', {'A': 'Multipath Fading akibat pantulan gelombang dari tubuh manusia dan benda bergerak yang saling memperkuat atau memperlemah secara acak', 'B': 'Pemberian kuota internet yang tidak merata oleh penyedia ISP', 'C': 'Kerusakan pada sirkuit motherboard komputer server', 'D': 'Penurunan tegangan baterai smartphone siswa secara serempak'}, 'A', 'PROBABILISTIC_REASONING', 'Multipath fading terjadi saat gelombang pantulan tiba di antena penerima dengan beda fase acak; interferensi konstruktif menaikkan sinyal, sedangkan interferensi destruktif menurunkannya.')], 'hard': [('Dalam merancang tautan nirkabel Point-to-Point antarkampus sejauh 1 km pada frekuensi 5.8 GHz, teknisi menghitung Free Space Path Loss (FSPL) sebesar 108 dB. Jika Tx Power = 17 dBm, gain kedua antena masing-masing 23 dBi, dan redaman kabel total 4 dB, berapakah perkiraan daya sinyal terima (Rx Power)?', {'A': '-49 dBm (17 + 23 + 23 - 4 - 108)', 'B': '-85 dBm', 'C': '-25 dBm', 'D': '-120 dBm'}, 'A', 'COMBINATORIAL_REASONING', 'Link Budget = Tx (17) + Gtx (23) + Grx (23) - LossKabel (4) - FSPL (108) = 63 - 112 = -49 dBm. Nilai -49 dBm sangat prima dan menjamin modulasi tertinggi.'), ('Ketika RSSI pada laptop siswa merosot dari -60 dBm menjadi -80 dBm karena siswa berpindah ke pojok ruangan, mengapa kecepatan transfer file riil anjlok drastis bukan hanya sebesar sepertiga melainkan turun dari 150 Mbps menjadi 12 Mbps?', {'A': 'Karena adaptor nirkabel menurunkan skema modulasi MCS dari 64-QAM rate 5/6 ke BPSK rate 1/2 untuk mempertahankan keutuhan data', 'B': 'Karena kabel jaringan router mengalami pemanasan', 'C': 'Karena kuota bandwidth internet siswa otomatis dipotong oleh sistem', 'D': 'Karena nomor port TCP otomatis berubah'}, 'A', 'PROPORTIONAL_REASONING', 'Hubungan antara RSSI dan throughput bersifat non-linier bertingkat; penurunan SNR memaksa algoritma Rate Adaptation melompat turun ke skema modulasi yang jauh lebih sederhana (BPSK).'), ('Teknisi ingin mengukur secara presisi nilai redaman kaca jendela berlapis film di lab nirkabel. Prosedur kontrol variabel manakah yang wajib diterapkan agar hasil pengukuran valid?', {'A': 'Mengukur RSSI pada jarak dan sudut elevasi yang persis sama, dengan daya AP konstan, saat kaca jendela ditutup rapat vs saat kaca dibuka penuh', 'B': 'Mengukur kaca di lab A pada siang hari lalu membandingkannya dengan kaca di lab B pada malam hari', 'C': 'Mengganti Access Point dengan model lain saat membuka jendela', 'D': 'Mengukur sinyal saat ada 20 siswa berkumpul di depan jendela'}, 'A', 'CONTROLLING_VARIABLES', 'Untuk mengisolasi nilai redaman material kaca film, parameter pemancar (Tx, frekuensi), jarak ukur, orientasi antena, dan lingkungan propagasi harus identik sempurna.'), ('Data log AP menunjukkan lantai derau (noise floor) naik dari -96 dBm menjadi -78 dBm. Jika daya sinyal RSSI stasiun adalah -72 dBm, berapakah nilai Signal-to-Noise Ratio (SNR) dan bagaimana status kelayakan koneksinya?', {'A': 'SNR = 6 dB (koneksi sangat buruk, tidak stabil, dan rentan putus total)', 'B': 'SNR = 150 dB (koneksi sangat prima)', 'C': 'SNR = -150 dB (tidak ada sinyal)', 'D': 'SNR = 24 dB (koneksi stabil untuk HD streaming)'}, 'A', 'CORRELATIONAL_REASONING', 'SNR = Signal - Noise = (-72 dBm) - (-78 dBm) = +6 dB. Syarat minimal koneksi Wi-Fi stabil adalah SNR >= 15-20 dB; nilai 6 dB memicu frame error rate yang sangat tinggi.'), ('Pada ruangan laboratorium nirkabel tertutup tanpa jalur Line of Sight (NLOS) langsung ke AP karena terhalang lemari besi, model distribusi probabilitas statistik manakah yang paling akurat menggambarkan fluktuasi sinyal terima?', {'A': 'Distribusi Rayleigh Fading', 'B': 'Distribusi Rician Fading', 'C': 'Distribusi Linier Konstan', 'D': 'Distribusi Poisson Terpangkas'}, 'A', 'PROBABILISTIC_REASONING', 'Ketika tidak terdapat komponen gelombang dominan garis pandang langsung (LoS), perpaduan banyak sinyal pantulan acak mengikuti fungsi kerapatan probabilitas Rayleigh.')]}

EXTRA_KC_BLUEPRINTS['WLAN_ROAMING_PROB'] = {'easy': [('Proses perpindahan koneksi perangkat klien nirkabel dari satu Access Point ke Access Point lain yang memiliki SSID sama secara mulus saat pengguna berjalan disebut...', {'A': 'Roaming (Handover)', 'B': 'Bridging', 'C': 'Subnetting', 'D': 'Cloning'}, 'A', 'CONTROLLING_VARIABLES', 'Roaming memungkinkan stasiun berpindah antar-BSSID dalam satu Extended Service Set (ESS) tanpa memutus sesi komunikasi data.'), ('Ambang batas kekuatan sinyal (Roaming Threshold) pada perangkat klien adalah tingkat nilai RSSI di mana klien mulai...', {'A': 'Memindai kanal frekuensi lain untuk mencari Access Point baru dengan sinyal yang lebih kuat', 'B': 'Mematikan fungsi radio Wi-Fi secara permanen', 'C': 'Menghapus seluruh berkas konfigurasi IP', 'D': 'Mengirimkan pesan darurat ke operator seluler'}, 'A', 'PROPORTIONAL_REASONING', 'Saat sinyal AP saat ini menyentuh batas roaming threshold (misal -70 atau -75 dBm), algoritma background scan diaktifkan untuk mengevaluasi AP alternatif.'), ('Agar proses roaming nirkabel antarkelas di lingkungan sekolah dapat berjalan dengan benar, syarat konfigurasi mendasar pada seluruh Access Point adalah...', {'A': 'Menggunakan nama SSID dan parameter keamanan (tipe enkripsi/kata sandi) yang identik pada segmen jaringan layer 2 yang sama', 'B': 'Menggunakan nama SSID yang berbeda-beda untuk tiap kelas', 'C': 'Menggunakan nomor kanal frekuensi yang sama persis di seluruh kelas', 'D': 'Menghubungkan AP menggunakan kabel telepon kawat tunggal'}, 'A', 'COMBINATORIAL_REASONING', 'Roaming dalam satu ESS mewajibkan keseragaman SSID dan kredensial keamanan agar perangkat klien dapat berpindah asosiasi tanpa menuntut intervensi input manual pengguna.'), ("Fenomena 'Sticky Client' pada jaringan nirkabel sekolah terjadi ketika perangkat laptop siswa...", {'A': 'Tetap bertahan menempel pada AP lama yang sinyalnya sudah sangat lemah meskipun siswa sudah duduk tepat di bawah AP baru yang sinyalnya kuat', 'B': 'Otomatis berpindah AP setiap 2 detik secara terus-menerus', 'C': 'Menolak terhubung ke jaringan kabel UTP', 'D': 'Mengalami kerusakan fisik pada antena eksternal'}, 'A', 'CONTROLLING_VARIABLES', 'Sticky Client terjadi karena keputusan roaming ditentukan oleh klien; driver kartu Wi-Fi yang agresivitas roaming-nya rendah menolak melepas AP lama selama sinyal belum benar-benar putus.'), ('Dalam arsitektur nirkabel standar IEEE 802.11 tradisional, pihak yang memegang kendali penuh untuk memutuskan kapan harus berpindah (roam) ke AP lain adalah...', {'A': 'Perangkat klien itu sendiri (berdasarkan driver adaptor nirkabel klien)', 'B': 'Access Point pemancar', 'C': 'Switch jaringan distribusi', 'D': 'Server DNS sekolah'}, 'A', 'PROBABILISTIC_REASONING', 'Keputusan roaming pada 802.11 bersifat client-driven; klien yang mengukur sinyal lokal dan menentukan saat yang tepat untuk mengirim Reassociation Request.')], 'medium': [('Parameter Hysteresis Margin (misal sebesar 5 dB) pada pengaturan roaming klien berfungsi untuk...', {'A': 'Mencegah fenomena ping-pong handover (berpindah bolak-balik terus-menerus antara dua AP) akibat fluktuasi acak sinyal di perbatasan sel', 'B': 'Menaikkan bandwidth download sebesar 500%', 'C': 'Mengganti alamat IP klien menjadi statis', 'D': 'Memperpanjang kabel daya Access Point'}, 'A', 'CONTROLLING_VARIABLES', 'Tanpa hysteresis, jika AP-1 = -70 dBm dan AP-2 = -69 dBm, sedikit fluktuasi noise sesaat akan memicu perpindahan asosiasi bolak-balik yang memutus aliran data.'), ('Standar IEEE 802.11k (Radio Resource Measurement) membantu mempercepat proses roaming dengan cara...', {'A': 'Memberikan daftar laporan tetangga (Neighbor Report) kepada klien sehingga klien tidak perlu memindai seluruh kanal spektrum satu per satu', 'B': 'Mematikan enkripsi sandi saat klien bergerak', 'C': 'Mengharuskan klien menggunakan kabel LAN', 'D': 'Menghubungkan klien langsung ke satelit'}, 'A', 'COMBINATORIAL_REASONING', '802.11k menyederhanakan pencarian kandidat AP; AP mengirimkan daftar kanal yang digunakan oleh AP tetangga terdekat, memangkas waktu pemindaian dari ~400 ms menjadi ~30 ms.'), ('Berapakah persentase tumpang tindih sel cakupan sinyal (cell overlap) yang direkomendasikan antardua Access Point bersebelahan agar transisi roaming suara/video berjalan mulus tanpa area mati?', {'A': 'Sekitar 15% hingga 20% pada batas sinyal -67 dBm', 'B': '0% (sel tidak boleh bersentuhan sama sekali)', 'C': '100% (kedua AP harus berada di titik koordinat yang sama)', 'D': 'Tepat 85%'}, 'A', 'CORRELATIONAL_REASONING', 'Overlap 15-20% pada ambang sinyal berkualitas (-67 dBm) memastikan klien dapat mendeteksi dan menyelesaikan reasosiasi ke AP baru sebelum sinyal AP lama mengalami degradasi ekstrem.'), ('Saat melakukan pemindaian aktif (active scan) mencari AP baru, radio klien mengirim frame Probe Request di kanal lain. Apa dampak proporsional penundaan pemindaian ini terhadap panggilan suara VoIP?', {'A': 'Dapat menimbulkan jeda audio (jitter/choppy audio) jika durasi pemindaian melampaui batas toleransi latensi suara (50-100 ms)', 'B': 'Panggilan suara otomatis berubah menjadi pesan teks SMS', 'C': 'Volume mikrofon ponsel otomatis naik menjadi maksimal', 'D': 'Nomor telepon lawan bicara otomatis terblokir'}, 'A', 'PROPORTIONAL_REASONING', 'Selama kartu nirkabel beralih kanal untuk memindai probe, kartu tidak dapat mengirim/menerima frame di kanal asal; jika berlangsung terlalu lama, buffer suara kosong dan audio terputus.'), ('Standar Fast BSS Transition (IEEE 802.11r) memangkas waktu jeda roaming (handover delay) di jaringan WPA2-Enterprise dari ~800 ms menjadi di bawah 50 ms. Hal ini dicapai melalui...', {'A': 'Melakukan pertukaran kunci keamanan awal dan negosiasi QoS dengan AP target sebelum klien memutuskan asosiasi dari AP asal', 'B': 'Menghapus seluruh enkripsi jaringan menjadi tanpa sandi', 'C': 'Mempercepat laju elektron pada kabel tembaga switch', 'D': 'Menggunakan protokol Bluetooth untuk transmisi data'}, 'A', 'PROBABILISTIC_REASONING', '802.11r melakukan pre-authentication key derivation melalui backbone kabel (Over-the-DS) atau melalui udara (Over-the-Air) sebelum perpindahan fisik, mengeliminasi handshake 802.1X ulang.')], 'hard': [("Untuk mengatasi masalah 'Sticky Client' pada jaringan lab sekolah yang padat, konfigurasi manakah pada controller Access Point yang paling tepat diterapkan?", {'A': 'Mengaktifkan Minimum RSSI / Client Disconnect Threshold pada nilai -75 dBm untuk memutuskan stasiun yang sinyalnya lemah secara paksa agar mencari AP baru', 'B': 'Menaikkan daya pancar AP menjadi 1000 Watt', 'C': 'Mematikan seluruh fitur keamanan WPA2', 'D': 'Menyembunyikan SSID pada jam istirahat'}, 'A', 'CONTROLLING_VARIABLES', 'Fitur kicking/minimum RSSI mengirim frame disassociation saat sinyal klien jatuh di bawah ambang batas, memaksa klien mengevaluasi ulang lingkungan radio dan terhubung ke AP terdekat.'), ('Pada pengujian transmisi streaming video saat siswa berjalan melewati 4 AP berturut-turut, sistem yang menerapkan 802.11r menghasilkan packet loss 0.2%, sedangkan sistem tanpa 802.11r menghasilkan packet loss 12%. Faktor proporsional apakah yang mendasari disparitas performa ini?', {'A': 'Selisih durasi jeda hening transmisi (handoff latency): 30 ms pada 802.11r vs 800 ms pada re-autentikasi penuh 802.1X', 'B': 'Kecepatan kabel listrik ke masing-masing AP berbeda', 'C': 'Suhu ruangan lorong yang dingin', 'D': 'Tipe sistem operasi laptop siswa yang berbeda merek'}, 'A', 'PROPORTIONAL_REASONING', 'Handoff latency yang panjang (800 ms) melampaui kapasitas buffer video streaming, memicu buffer underrun dan pembuangan paket data selama proses 4-way handshake ulang.'), ('Kombinasi tiga standar IEEE yang bekerja bersamaan untuk menciptakan pengalaman roaming kelas enterprise paling optimal (Fast Roaming Trio) adalah...', {'A': 'IEEE 802.11k (Neighbor Reports), IEEE 802.11v (BSS Transition Management), dan IEEE 802.11r (Fast Transition)', 'B': 'IEEE 802.3, IEEE 802.5, dan IEEE 802.1Q', 'C': 'IEEE 802.11a, IEEE 802.11b, dan IEEE 802.11g', 'D': 'IEEE 1394, USB 3.0, dan HDMI 2.1'}, 'A', 'COMBINATORIAL_REASONING', 'Trio 802.11k/v/r menyatukan pemetaan tetangga (11k), pembimbingan asosiasi dari controller (11v), dan pemotongan waktu autentikasi pertukaran kunci (11r).'), ('Fenomena tautan asimetris (Asymmetric Link) terjadi saat AP memancar dengan daya sangat tinggi (100 mW / 20 dBm) sedangkan smartphone siswa hanya berdaya 15 mW (12 dBm). Apa akibatnya saat proses roaming?', {'A': 'Siswa melihat sinyal Wi-Fi di ponsel tampak penuh, namun ponsel tidak dapat mengirimkan data balik ke AP karena sinyal balik terlalu lemah untuk mencapai antena AP', 'B': 'Baterai smartphone siswa akan terisi ulang melalui udara', 'C': 'Throughput download ponsel otomatis mencapai 10 Gbps', 'D': 'AP akan meledak karena kelebihan daya'}, 'A', 'CORRELATIONAL_REASONING', 'Korelasi ketidakseimbangan daya pancar (Tx power mismatch): ponsel mendengar beacon AP dengan kuat sehingga menolak roaming, padahal frame ack dari ponsel tidak sampai ke AP (dead link).'), ('Model rantai Markov digunakan untuk memprediksi probabilitas perpindahan klien dari sel AP-A ke AP-B atau AP-C di persimpangan lorong. Jika probabilitas transisi ke AP-B adalah 0.7 dan ke AP-C adalah 0.3, strategi alokasi sumber daya nirkabel yang paling efisien adalah...', {'A': 'Melakukan pra-alokasi tiket kunci autentikasi (PMK caching) prioritas utama pada AP-B', 'B': 'Mematikan pemancar radio pada AP-C', 'C': 'Memindahkan seluruh kabel LAN ke AP-A', 'D': 'Mengurangi daya listrik pada AP-B'}, 'A', 'PROBABILISTIC_REASONING', 'Pendekatan prediktif cerdas memanfaatkan matriks probabilitas transisi untuk menyiapkan kunci sesi lebih awal di AP dengan probabilitas kunjungan tertinggi (AP-B).')]}

EXTRA_KC_BLUEPRINTS['WLAN_CHANNEL_COLLISION'] = {'easy': [('Karakteristik mendasar dari media nirkabel Wi-Fi sebagai media transmisi bersama (shared medium) adalah bersifat...', {'A': 'Setengah dupleks (Half-Duplex), di mana perangkat tidak dapat memancarkan dan menerima data pada frekuensi yang sama secara bersamaan', 'B': 'Dupleks penuh (Full-Duplex) tanpa hambatan', 'C': 'Simplex searah seperti siaran radio FM komersial', 'D': 'Multiplexing kabel tembaga terisolasi'}, 'A', 'CONTROLLING_VARIABLES', 'Karena radio Wi-Fi menggunakan satu saluran frekuensi bersama, pemancar lokal akan menenggelamkan sinyal penerima jika memancarkan dan menerima serentak; komunikasi wajib bergantian (half-duplex).'), ('Protokol kendali akses media yang digunakan pada jaringan nirkabel IEEE 802.11 untuk mencegah tabrakan data di udara adalah...', {'A': 'CSMA/CA (Carrier Sense Multiple Access with Collision Avoidance)', 'B': 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection)', 'C': 'Token Ring Passing', 'D': 'ALOHA Murni Tanpa Sensor'}, 'A', 'CONTROLLING_VARIABLES', 'Wi-Fi menggunakan CSMA/CA yang berfokus pada pencegahan tabrakan (avoidance) menggunakan slot waktu acak sebelum transmisi dimulai.'), ('Mengapa jaringan Wi-Fi tidak dapat menggunakan mekanisme Collision Detection (CSMA/CD) seperti halnya jaringan kabel Ethernet LAN?', {'A': 'Karena daya pancar pemancar lokal jauh lebih besar daripada sinyal lemah yang diterima dari stasiun lain, sehingga radio tidak dapat mendeteksi tabrakan saat sedang memancar', 'B': 'Karena kabel serat optik tidak mendukung gelombang radio', 'C': 'Karena protokol CSMA/CD hanya berlaku untuk sistem operasi Apple', 'D': 'Karena undang-undang telekomunikasi melarang pendeteksian tabrakan di udara'}, 'A', 'CONTROLLING_VARIABLES', "Perbedaan daya antara sinyal kirim dan terima mencapai jutaan kali lipat; stasiun yang sedang memancar mengalami 'kebutaan sesaat' terhadap sinyal stasiun lain yang bertabrakan di udara."), ("Ketika 36 siswa di satu kelas secara serentak menekan tombol 'Submit' pada aplikasi kuis nirkabel di detik yang sama, apa yang terjadi pada antrean media radio?", {'A': 'Tingkat tabrakan paket (collision rate) melonjak drastis, memicu retransmisi berulang dan penurunan kecepatan akses secara serentak', 'B': 'Access Point otomatis menggandakan jumlah antenanya', 'C': 'Kuis siswa yang pertama menekan tombol otomatis dinilai 100', 'D': 'Alamat IP siswa otomatis terformat ulang'}, 'A', 'CORRELATIONAL_REASONING', 'Korelasi kepadatan akses bersama: lonjakan stasiun yang bersaing memperebutkan media meningkatkan probabilitas dua stasiun memilih slot waktu hening yang sama, menghasilkan tabrakan data.'), ('Dua buah laptop siswa berada di dekat AP. Keduanya selesai menunggu waktu jeda DIFS dan secara acak memilih nilai slot backoff yang sama persis (misal slot 3). Peluang terjadinya tabrakan frame pada awal transmisi adalah...', {'A': 'Pasti terjadi tabrakan (100% collision)', 'B': '0% karena AP dapat memisahkan paket', 'C': '50% tergantung arah mata angin', 'D': 'Tidak dapat diprediksi secara matematis'}, 'A', 'PROBABILISTIC_REASONING', 'Jika dua perangkat mentransmisikan frame pada slot waktu yang sama persis di kanal yang sama, gelombang radio akan saling bertumpuk di antena AP dan merusak paket (100% collision).')], 'medium': [('Mekanisme Random Backoff pada CSMA/CA bekerja dengan cara mengundi bilangan bulat acak di dalam rentang Jendela Persaingan (Contention Window / CW). Apa yang terjadi pada nilai CW jika terjadi tabrakan data berulang?', {'A': 'Ukuran jendela CW digandakan secara eksponensial (dari CWmin hingga mencapai CWmax) untuk memperkecil probabilitas tabrakan berikutnya', 'B': 'Ukuran CW langsung diturunkan menjadi nol', 'C': 'Nilai CW dikunci pada angka 1', 'D': 'Access Point mematikan seluruh slot backoff'}, 'A', 'PROBABILISTIC_REASONING', 'Binary Exponential Backoff menggandakan rentang undian (misal 15 -> 31 -> 63 -> 127...); rentang yang semakin lebar memperkecil peluang dua stasiun memilih slot yang identik saat media padat.'), ("Fenomena 'Hidden Node Problem' pada jaringan nirkabel terjadi ketika...", {'A': 'Dua stasiun klien berada pada posisi saling terhalang atau berjauhan sehingga tidak dapat saling mendengar, namun keduanya terhubung ke AP yang sama', 'B': 'Access Point disembunyikan di dalam lemari brankas', 'C': 'Kabel internet ISP sengaja diputus oleh administrator', 'D': 'Komputer server tidak memiliki kartu grafis'}, 'A', 'CONTROLLING_VARIABLES', 'Hidden node menggagalkan fungsi Carrier Sense fisik; Klien A mengira kanal kosong karena tidak mendengar Klien B, padahal Klien B sedang mengirim ke AP, memicu tabrakan di AP penerima.'), ('Mekanisme jabat tangan virtual RTS/CTS (Request to Send / Clear to Send) dirancang khusus untuk mengatasi masalah...', {'A': 'Hidden Node Problem dengan cara memesan media radio menggunakan Network Allocation Vector (NAV)', 'B': 'Kabel LAN yang terlepas dari saklar', 'C': 'Kerusakan adaptor daya listrik AP', 'D': 'Siswa yang lupa kata sandi akun ujian'}, 'A', 'COMBINATORIAL_REASONING', 'RTS/CTS mengirimkan frame kendali pendek yang memuat informasi durasi transmisi; frame CTS dari AP didengar oleh seluruh stasiun sekitar (termasuk hidden node), menyuruh mereka menahan transmisi (NAV).'), ('Pada kondisi kanal nirkabel yang memiliki tingkat interferensi tinggi, mengapa pengiriman frame data berukuran besar (MTU 1500 byte) memiliki probabilitas kegagalan yang lebih tinggi dibanding frame berukuran kecil?', {'A': 'Frame besar membutuhkan waktu transmisi udara (airtime) lebih lama, sehingga memperbesar probabilitas terinterupsi oleh lonjakan derau atau tabrakan', 'B': 'Frame besar tidak dapat dibaca oleh sistem operasi Windows', 'C': 'Gelombang radio menjadi lebih berat secara fisik saat membawa data besar', 'D': 'Antena Access Point akan mengalami kelelahan mekanik'}, 'A', 'PROPORTIONAL_REASONING', 'Waktu pengiriman berbanding lurus dengan ukuran frame; semakin lama paket mengudara di saluran berisik, semakin besar kemungkinan satu bit data rusak yang menggagalkan seluruh frame (CRC error).'), ("Peningkatan metrik 'Retries' (upaya kirim ulang paket) hingga melampaui 30% pada log diagnostik Access Point di laboratorium berkorelasi langsung dengan...", {'A': 'Penurunan tajam efisiensi kapasitas saluran (airtime) dan peningkatan latensi respons aplikasi siswa', 'B': 'Penghematan daya listrik pada baterai klien', 'C': 'Peningkatan kecepatan internet ISP secara otomatis', 'D': 'Penambahan kuota penyimpanan harddisk server'}, 'A', 'CORRELATIONAL_REASONING', 'Retransmisi menghabiskan slot waktu berharga untuk mengirim ulang paket yang sama berulang kali, merampas airtime dari paket baru dan memperlambat seluruh jaringan.')], 'hard': [('Mengapa administrator jaringan tidak mengaktifkan mekanisme RTS/CTS untuk seluruh paket data melainkan hanya untuk paket yang ukurannya melebihi ambang batas (RTS Threshold)?', {'A': 'Karena pertukaran frame RTS dan CTS itu sendiri menimbulkan beban overhead transmisi yang justru memboroskan bandwidth jika digunakan pada paket-paket kecil', 'B': 'Karena frame RTS hanya dapat dikirimkan pada malam hari', 'C': 'Karena frame CTS membutuhkan pembayaran lisensi per frame', 'D': 'Karena router MikroTik akan otomatis terkunci jika menerima paket RTS'}, 'A', 'PROPORTIONAL_REASONING', 'RTS/CTS menambah 2 frame overhead sebelum data dikirim; jika diterapkan pada paket kecil (misal ACK TCP 40 byte), overhead kontrol justru lebih besar daripada data aktual, menurunkan efisiensi jaringan.'), ('Berdasarkan model analitis Bianchi untuk DCF IEEE 802.11, probabilitas terjadinya tabrakan (p) pada media akses bersama berbanding lurus secara non-linier dengan...', {'A': 'Jumlah stasiun yang aktif bersaing memperebutkan kanal nirkabel secara simultan', 'B': 'Panjang kabel listrik yang menyuplai daya ke saklar', 'C': 'Jumlah karakter pada nama SSID sekolah', 'D': 'Kecepatan kipas prosesor di komputer klien'}, 'A', 'PROBABILISTIC_REASONING', 'Model Bianchi membuktikan bahwa probabilitas collision $p = 1 - (1 - \\tau)^{N-1}$ meningkat tajam seiring bertambahnya jumlah stasiun bersaing (N), membatasi throughput maksimal CSMA/CA.'), ('Seorang teknisi ingin menguji efektivitas pengaktifan RTS/CTS dalam mengatasi hidden node di ruang lab berbentuk L. Desain eksperimen kontrol variabel yang valid adalah...', {'A': 'Mengukur throughput total kedua klien pada posisi terhalang dinding yang sama persis, dengan beban trafik identik, saat RTS Threshold disetel 2346 (non-aktif) vs disetel 500 (aktif)', 'B': 'Menguji satu klien di dalam lab dan klien lain di lapangan sepak bola', 'C': 'Mengganti merek Access Point saat menguji RTS/CTS', 'D': 'Mematikan koneksi salah satu klien saat pengujian RTS berlangsung'}, 'A', 'CONTROLLING_VARIABLES', 'Untuk mengisolasi dampak mekanisme RTS/CTS, posisi geografis hidden node, pola lalu lintas data pengirim, dan kondisi kanal radio wajib dijaga identik antara kedua sesi pengujian.'), ("Masalah 'Exposed Node Problem' pada jaringan nirkabel multi-sel menyebabkan stasiun menunda transmisi secara tidak perlu karena...", {'A': 'Stasiun mendengar transmisi stasiun tetangga dan mengira kanal sibuk, padahal stasiun penerima tujuannya berada di arah berlawanan dan tidak akan mengalami tabrakan', 'B': 'Kabel jaringan terpapar sinar matahari langsung', 'C': 'Casing luar Access Point mengalami kebocoran fisik', 'D': 'Server sekolah mengirimkan frame peringatan darurat'}, 'A', 'COMBINATORIAL_REASONING', 'Exposed node adalah kebalikan dari hidden node: Carrier Sense fisik terlalu sensitif mendengar transmisi yang sebenarnya tidak akan menimbulkan tabrakan di titik penerima yang berbeda, membuang kapasitas kanal.'), ('Pada standar IEEE 802.11e / WMM (Wireless Multimedia QoS), paket suara (Voice) diprioritaskan di atas paket data umum (Best Effort) dengan cara...', {'A': 'Memberikan nilai Arbitration Inter-Frame Space (AIFS) yang lebih pendek dan rentang Contention Window yang lebih kecil pada paket suara', 'B': 'Mematikan seluruh koneksi data umum saat ada panggilan suara', 'C': 'Mengirimkan paket suara melalui kabel telepon analog', 'D': 'Mengganti frekuensi radio menjadi frekuensi suara manusia'}, 'A', 'CORRELATIONAL_REASONING', 'Dengan jeda AIFS yang lebih pendek dan CWmin yang kecil, paket antrean suara secara probabilistik akan selalu memenangkan undian slot backoff dibanding paket data umum, menjamin latensi rendah.')]}

EXTRA_KC_BLUEPRINTS['ICMP_CONNECTIVITY'] = {'easy': [('Perintah dasar berbasis Command Prompt / Terminal yang digunakan teknisi jaringan untuk menguji konektivitas ketercapaian layer 3 (IP) ke host tujuan adalah...', {'A': 'ping', 'B': 'ipconfig', 'C': 'netstat', 'D': 'tracert'}, 'A', 'CONTROLLING_VARIABLES', "Perintah 'ping' mengirimkan paket ICMP Echo Request dan mendengarkan paket Echo Reply untuk memverifikasi ketercapaian host ujung-ke-ujung."), ('Dua tipe pesan protokol ICMP utama yang saling berpasangan dalam proses pengujian perintah ping adalah...', {'A': 'ICMP Type 8 (Echo Request) dan ICMP Type 0 (Echo Reply)', 'B': 'ICMP Type 3 dan ICMP Type 5', 'C': 'TCP SYN dan TCP ACK', 'D': 'DNS Query dan DNS Response'}, 'A', 'COMBINATORIAL_REASONING', 'Pengujian ping standar menggunakan ICMP Type 8 (pesan permintaan gema dari pengirim) dan mengharapkan respon ICMP Type 0 (pesan balasan gema dari penerima).'), ('Nilai Round-Trip Time (RTT) yang dilaporkan dalam satuan milidetik (ms) pada hasil uji ping merepresentasikan...', {'A': 'Waktu tempuh bolak-balik yang dibutuhkan paket mulai dari saat dikirimkan hingga balasan gema diterima kembali oleh pengirim', 'B': 'Lama waktu komputer dinyalakan sejak pagi', 'C': 'Jumlah paket data yang berhasil diunduh dalam 1 jam', 'D': 'Kecepatan putaran harddisk pada komputer server tujuan'}, 'A', 'PROPORTIONAL_REASONING', 'RTT mengukur latensi dua arah: waktu transmisi pergi + waktu pemrosesan di host tujuan + waktu transmisi balik (Total Round-Trip Latency).'), ('Parameter Time to Live (TTL) pada header paket IP balasan uji ping berfungsi untuk...', {'A': 'Membatasi masa hidup paket dengan mengurangi nilai hop di setiap router demi mencegah paket berputar selamanya di jaringan jika terjadi loop', 'B': 'Menentukan batas kedaluwarsa lisensi sistem operasi Windows', 'C': 'Mengukur sisa baterai pada laptop penguji', 'D': 'Menghitung jumlah pengguna aktif di laboratorium'}, 'A', 'CONTROLLING_VARIABLES', 'Setiap kali paket melewati router (hop), nilai TTL dikurangi 1; jika TTL mencapai 0, router membuang paket dan mengembalikan pesan ICMP Time Exceeded.'), ("Jika hasil pengujian ping 10 kali ke default gateway laboratorium menunjukkan statistik 'Sent = 10, Received = 10, Lost = 0 (0% loss)' dengan RTT rata-rata 2 ms, probabilitas transmisi data aplikasi lokal berjalan lancar adalah...", {'A': 'Sangat tinggi (mendekati 100%) karena konektivitas fisik dan protokol lapisan jaringan terbukti andal tanpa kehilangan paket', 'B': '0% karena uji ping tidak membuktikan adanya kabel', 'C': 'Tepat 50% tergantung merk saklar', 'D': 'Tidak dapat ditentukan sama sekali'}, 'A', 'PROBABILISTIC_REASONING', 'Hasil 0% loss dan latensi rendah 2 ms mengonfirmasi integritas layer 1 (fisik), layer 2 (data link), dan layer 3 (IP) pada segmen LAN lokal.')], 'medium': [('Mengapa nilai RTT ping pada jaringan nirkabel (Wi-Fi) laboratorium seringkali mengalami fluktuasi tajam (jitter dari 3 ms melompat ke 120 ms) dibanding jaringan kabel UTP yang stabil 1 ms?', {'A': 'Karena adanya persaingan media akses CSMA/CA, retransmisi akibat derau udara, dan mekanisme adaptasi modulasi dinamis pada radio', 'B': 'Karena gelombang radio berjalan lebih lambat dibanding arus listrik di kabel tembaga', 'C': 'Karena adaptor Wi-Fi sengaja memperlambat ping untuk menghemat listrik', 'D': 'Karena kabel serat optik ISP bergoyang tertiup angin'}, 'A', 'CORRELATIONAL_REASONING', 'Korelasi variabilitas media nirkabel: antrean contention window acak dan retransmisi paket di udara menimbulkan variasi waktu tunggu paket (jitter) yang tidak ada pada kabel tembaga dedicated.'), ("Ketika teknisi melakukan ping ke sebuah alamat IP dan menerima balasan pesan 'TTL Expired in Transit', akar masalah jaringan yang sedang terjadi adalah...", {'A': 'Terjadinya jalur memutar tanpa akhir (Routing Loop) di antara dua atau lebih router perantara yang salah dikonfigurasi', 'B': 'Kabel UTP yang digunakan terlalu panjang melampaui 100 meter', 'C': 'Komputer tujuan dimatikan oleh pemiliknya', 'D': 'Server DNS sekolah salah memasukkan nama domain'}, 'A', 'CONTROLLING_VARIABLES', 'Pesan TTL Expired (ICMP Type 11 Code 0) dikirim oleh router ketika nilai TTL paket jatuh ke nol saat dipantulkan bolak-balik dalam siklus loop routing yang salah.'), ("Perintah pengujian MTU `ping -f -l 1472 192.168.1.1` pada Windows menggunakan opsi `-f` (Don't Fragment) dan `-l` (Buffer Size). Mengapa angka 1472 byte yang diuji untuk memastikan paket pas dengan MTU standar Ethernet 1500 byte?", {'A': 'Karena payload ICMP 1472 byte ditambah header IP (20 byte) dan header ICMP (8 byte) tepat berjumlah 1500 byte', 'B': 'Karena angka 1472 adalah tahun ditemukannya jaringan komputer', 'C': 'Karena sistem operasi Windows memotong otomatis 28 byte untuk cadangan memori RAM', 'D': 'Karena router membatasi ukuran ping maksimal hanya genap'}, 'A', 'PROPORTIONAL_REASONING', 'Perhitungan proporsional ukuran frame: Total Ukuran Paket = Payload ICMP (1472 byte) + Header ICMP (8 byte) + Header IP (20 byte) = 1500 byte (batas MTU maksimum Ethernet tanpa fragmentasi).'), ('Dalam pengujian ping dari Laptop A (192.168.10.5) melewati dua router menuju Server B (10.0.0.1), komponen header IP manakah yang nilainya selalu berubah di setiap lompatan hop router?', {'A': 'Nilai Time to Live (TTL) dan IP Header Checksum', 'B': 'Alamat Source IP dan Destination IP asli paket', 'C': 'Versi protokol IPv4', 'D': 'Panjang total paket data'}, 'A', 'COMBINATORIAL_REASONING', 'Router meneruskan paket dengan mempertahankan Source dan Destination IP asli, namun wajib mengurangi nilai TTL sebesar 1 dan menghitung ulang Header Checksum pada setiap hop.'), ('Hasil uji ping berkelanjutan sebanyak 100 kali ke server video konferensi menunjukkan 8 paket mengalami timeout (8% packet loss). Dampak apa yang dialami siswa saat melakukan video call?', {'A': 'Audio sesekali terputus-putus dan video mengalami patah-patah (frame freeze) karena protokol real-time UDP tidak mentolerir kehilangan paket di atas 2-3%', 'B': 'Laptop siswa otomatis me-restart ulang', 'C': 'Gambar video berubah menjadi hitam putih', 'D': 'Kecepatan kipas laptop otomatis naik 80%'}, 'A', 'PROBABILISTIC_REASONING', 'Aplikasi komunikasi real-time (RTP/UDP) tidak melakukan retransmisi paket; packet loss 8% melampaui kemampuan algoritma packet loss concealment (PLC), merusak kejelasan suara dan gambar.')], 'hard': [('Utilitas diagnostik `tracert` (pada Windows) atau `traceroute` (pada Linux) mampu memetakan seluruh hop router di sepanjang jalur perjalanan paket dengan teknik cerdik, yaitu...', {'A': "Mengirimkan paket ICMP/UDP secara berurutan dengan memanipulasi nilai TTL mulai dari 1, 2, 3, dan seterusnya untuk memancing balasan pesan 'TTL Expired' dari setiap router", 'B': 'Mengakses kamera pengawas di setiap gedung router', 'C': 'Menebak alamat IP router berdasarkan nama kota', 'D': 'Mengirimkan sinyal radar elektromagnetik berkekuatan tinggi'}, 'A', 'COMBINATORIAL_REASONING', 'Dengan menyetel TTL=1, router pertama membalas dengan ICMP Time Exceeded (identitas terungkap); lalu TTL=2 memancing balasan router kedua, dan seterusnya hingga mencapai host tujuan.'), ('Ketika link internet sekolah mengalami saturasi unggahan (upload penuh 100%), latensi ping ke server eksternal melonjak dari 15 ms menjadi 650 ms tanpa ada paket yang drop. Fenomena jaringan apakah yang terjadi?', {'A': 'Bufferbloat, di mana paket ping tertahan lama di dalam antrean buffer router yang terlalu besar sebelum dapat ditransmisikan ke jalur keluar', 'B': 'Kabel serat optik bawah tanah memuai karena panas matahari', 'C': 'Kartu grafis komputer server mengalami overheat', 'D': 'Protokol ICMP otomatis diubah menjadi protokol BitTorrent'}, 'A', 'CORRELATIONAL_REASONING', 'Korelasi antrean: Bufferbloat terjadi saat router menampung terlalu banyak paket di buffer antrean daripada membuangnya; paket tetap terkirim tapi mengalami delay antrean (queuing delay) yang masif.'), ('Seorang teknisi ingin membedakan secara presisi berapa porsi latensi transmisi fisik kabel dan berapa porsi latensi proses internal pada pengujian ping antardua lab. Prosedur eksperimen kontrol variabel yang tepat adalah...', {'A': 'Mengukur RTT saat beban CPU router 0% (idle) vs 100% pada panjang kabel tetap, lalu mengukur variasi panjang kabel pada beban CPU konstan', 'B': 'Mengganti seluruh sistem operasi komputer saat kabel diganti', 'C': 'Mengukur latensi saat listrik sekolah padam', 'D': 'Mengukur waktu menggunakan stopwatch tangan manual'}, 'A', 'CONTROLLING_VARIABLES', 'Untuk mengisolasi waktu tempuh propagasi fisik dari delay pemrosesan router, parameter beban trafik dan beban CPU router harus dikendalikan secara mandiri.'), ('Pada pengujian ping dengan ukuran payload data kecil (32 byte), berapakah persentase beban tambahan (overhead) header jaringan (Ethernet 14 byte + IP 20 byte + ICMP 8 byte = 42 byte) terhadap total ukuran frame yang ditransmisikan (74 byte)?', {'A': 'Sekitar 56.7% (42 / 74)', 'B': 'Tepat 10%', 'C': 'Kurang dari 1%', 'D': '99.9%'}, 'A', 'PROPORTIONAL_REASONING', 'Perhitungan rasio overhead: Total Frame = Payload (32) + Overhead Header (42) = 74 byte. Persentase overhead = 42 / 74 = 56.7%, membuktikan bahwa transmisi payload kecil sangat tidak efisien dalam pemanfaatan bandwidth.'), ('Sistem deteksi intrusi jaringan (NIDS) memantau lalu lintas ICMP. Jika terdeteksi lebih dari 5.000 paket ICMP Echo Request per detik yang ditujukan ke satu alamat IP server dari berbagai alamat IP acak, kesimpulan ancaman probabilistik yang paling tepat adalah...', {'A': 'Sedang terjadi serangan distributed denial-of-service (DDoS) jenis ICMP Flood / Ping Flood untuk melumpuhkan antrean pemrosesan server', 'B': 'Ada siswa yang sedang mengetik perintah ping dengan sangat cepat menggunakan keyboard mekanik', 'C': 'Kabel internet sekolah sedang mengalami proses pendinginan otomatis', 'D': 'Server sedang memperbarui sistem operasi secara resmi'}, 'A', 'PROBABILISTIC_REASONING', 'Frekuensi ping ekstrem (>5.000 pps) melampaui perilaku manusia atau pemantauan sah, dengan probabilitas >99.9% merupakan serangan DoS untuk membanjiri bandwidth dan sumber daya CPU korban.')]}

EXTRA_KC_BLUEPRINTS['ICMP_TROUBLE_DHU'] = {'easy': [("Arti dari pesan galat 'Destination Host Unreachable' yang muncul pada hasil pengujian perintah ping adalah...", {'A': 'Komputer pengirim atau router gateway perantara tidak dapat menemukan rute atau tidak berhasil menyelesaikan alamat fisik (MAC) host tujuan', 'B': 'Komputer tujuan menolak menerima paket karena memori harddisk penuh', 'C': 'Kecepatan internet komputer pengirim terlalu tinggi', 'D': 'Kabel monitor komputer pengirim mengalami korsleting'}, 'A', 'CONTROLLING_VARIABLES', 'Destination Host Unreachable (ICMP Type 3) menandakan kegagalan pengiriman di lapisan jaringan atau tautan data; pengirim aktif diberi tahu bahwa host tujuan tidak dapat dijangkau.'), ("Perangkat jaringan manakah yang umumnya mengirimkan balasan pesan galat ICMP 'Destination Host Unreachable' kembali ke komputer siswa?", {'A': 'Router default gateway lokal atau tumpukan protokol TCP/IP di komputer siswa itu sendiri', 'B': 'Server Google pusat di Amerika', 'C': 'Kabel konektor RJ-45', 'D': 'Monitor layar komputer'}, 'A', 'CONTROLLING_VARIABLES', 'Jika host di subnet lokal tidak membalas ARP, komputer pengirim sendiri yang memunculkan pesan; jika host di remote subnet tak terjangkau, router gateway yang mengirimkan pesan ICMP Type 3.'), ("Komputer A memiliki IP 192.168.1.10/24 dan Komputer B memiliki IP 192.168.1.20/28. Mengapa saat Komputer B melakukan ping ke Komputer A muncul galat 'Destination Host Unreachable' padahal keduanya terhubung ke switch yang sama?", {'A': 'Karena subnet /28 hanya mencakup IP 192.168.1.1 hingga 192.168.1.14; Komputer B menganggap IP 1.20 berada di luar subnet lokalnya dan mencari gateway yang belum dikonfigurasi', 'B': 'Karena switch hanya dapat membaca alamat IP genap', 'C': 'Karena kabel UTP yang digunakan harus kabel cross-over', 'D': 'Karena angka 28 lebih besar dari angka 24'}, 'A', 'COMBINATORIAL_REASONING', 'Ketidakcocokan subnet mask memecah logika jaringan: Komputer B dengan /27 atau /28 melihat IP A (1.10) berada di luar jaringan lokalnya, sehingga paket dilempar ke gateway; tanpa gateway, muncul DHU.'), ('Pada jaringan LAN lokal yang sama, protokol yang bertugas mencari alamat perangkat keras (MAC Address) dari alamat IP tujuan sebelum paket ping dikirimkan adalah...', {'A': 'Address Resolution Protocol (ARP)', 'B': 'Dynamic Host Configuration Protocol (DHCP)', 'C': 'Simple Network Management Protocol (SNMP)', 'D': 'Network Time Protocol (NTP)'}, 'A', 'CORRELATIONAL_REASONING', 'Pengirim wajib mengisi header frame Ethernet dengan MAC tujuan; protokol ARP menyiarkan ARP Request untuk memetakan IP menjadi MAC; jika ARP gagal, ping gagal dengan DHU.'), ("Jika pengujian koneksi ke server ujian sekolah menghasilkan balasan 'Destination Host Unreachable' secara terus-menerus, probabilitas aplikasi web ujian dapat diakses di browser adalah...", {'A': '0% (pasti gagal total) karena jalur layer 3 tidak terbentuk sehingga jabat tangan TCP SYN tidak dapat terkirim sama sekali', 'B': '100% lancar tanpa gangguan', 'C': 'Tergantung browser yang digunakan (Chrome vs Firefox)', 'D': '50% jika halaman web di-refresh berulang kali'}, 'A', 'PROBABILISTIC_REASONING', 'Aplikasi web berjalan di atas TCP layer 4 yang membutuhkan ketercapaian IP layer 3; jika pesan DHU muncul, koneksi layer 3 mati total sehingga pertukaran paket TCP mustahil terjadi.')], 'medium': [("Siswa di lab TKJ melakukan ping ke komputer temannya pada IP 192.168.1.50 di subnet yang sama dan muncul pesan 'Reply from 192.168.1.10: Destination host unreachable'. Apa yang sedang terjadi di kabel jaringan komputer tujuan (1.50)?", {'A': 'Komputer tujuan dalam kondisi mati atau kabel jaringannya terlepas dari switch, sehingga komputer pengirim tidak menerima balasan ARP Reply', 'B': 'Komputer tujuan sedang mengunduh file dengan kecepatan terlalu tinggi', 'C': 'Kabel jaringan komputer pengirim terpasang terbalik', 'D': 'Router internet sedang kehabisan kuota pulsa'}, 'A', 'CONTROLLING_VARIABLES', "Komputer pengirim (192.168.1.10) membroadcast ARP Request 'Who has 192.168.1.50?'; karena host 1.50 mati/terlepas, tidak ada jawaban ARP, sehingga stack IP 1.10 memunculkan DHU."), ("Ketika melakukan ping ke alamat publik 8.8.8.8, komputer siswa memunculkan pesan 'Reply from 192.168.1.1: Destination net unreachable'. Penyebab paling logis pada router gateway (192.168.1.1) adalah...", {'A': 'Tabel routing pada router gateway tidak memiliki rute default (Default Route: dst-address=0.0.0.0/0) yang mengarah ke antarmuka modem ISP', 'B': 'Komputer siswa belum memasang antivirus', 'C': 'Lampu LED pada switch berwarna hijau bukan kuning', 'D': 'Kabel power router gateway belum dicolokkan ke listrik'}, 'A', 'CORRELATIONAL_REASONING', 'Jika router menerima paket untuk jaringan luar namun tabel routing-nya tidak memiliki rute spesifik maupun rute default (0.0.0.0/0), router mengembalikan pesan ICMP Type 3 Code 0 (Net Unreachable).'), ('Sebuah host memiliki alamat IP 192.168.5.60/26 dan mencoba melakukan ping ke 192.168.5.65/26 tanpa konfigurasi default gateway. Mengapa muncul pesan galat Destination Host Unreachable?', {'A': 'Karena pada prefix /26, IP 1.60 berada di blok subnet pertama (0-63), sedangkan IP 1.65 berada di blok subnet kedua (64-127), sehingga membutuhkan gateway perantara', 'B': 'Karena selisih kedua angka IP hanya 5', 'C': 'Karena angka 60 adalah bilangan genap dan 65 bilangan ganjil', 'D': 'Karena kabel UTP tidak dapat menghitung angka di atas 50'}, 'A', 'PROPORTIONAL_REASONING', 'Perhitungan matematis subnet /26 (kelipatan 64): Subnet 1: 192.168.5.0 - .63; Subnet 2: 192.168.5.64 - .127. Karena beda subnet, pengirim menolak mengirim ARP lokal dan membutuhkan router.'), ("Administrator lab TKJ mengamati tabel ARP pada router MikroTik. Jika status entri IP sebuah komputer siswa menunjukkan keterangan 'incomplete', pesan galat apakah yang akan diterima komputer lain saat mencoba ping ke IP tersebut?", {'A': 'Destination Host Unreachable', 'B': 'Reply from 0.0.0.0: bytes=32 time<1ms', 'C': 'Request Timed Out', 'D': '200 OK Connection Established'}, 'A', 'COMBINATORIAL_REASONING', "Status 'incomplete' pada tabel ARP membuktikan bahwa router telah mengirimkan ARP Request namun tidak pernah menerima balasan MAC address dari host terkait, memicu pesan DHU."), ('Dalam praktikum konfigurasi IP statis oleh 30 siswa baru di lab TKJ, kesalahan manusia (human error) manakah yang secara probabilistik paling sering memicu munculnya pesan Destination Host Unreachable saat mengakses internet?', {'A': 'Salah mengetik angka pada kolom Default Gateway atau mengosongkan nilai Default Gateway pada properti IPv4', 'B': 'Mengetik nama komputer dengan huruf kecil semua', 'C': 'Menggunakan mouse bermerek berbeda dengan keyboard', 'D': 'Mengatur resolusi layar monitor terlalu terang'}, 'A', 'PROBABILISTIC_REASONING', 'Tanpa gateway yang valid, komputer lokal tidak tahu harus melempar paket ke mana saat tujuan berada di luar subnet lokal, sehingga stack lokal langsung membatalkan transmisi dengan DHU.')], 'hard': [("Pada router MikroTik laboratorium, rute statis ke jaringan server ujian `dst-address=10.10.10.0/24 gateway=ether2` terpasang di tabel routing, namun kabel di port ether2 dalam status 'link down' (tercabut). Kode ICMP spesifik apakah yang dikembalikan router ke klien?", {'A': 'ICMP Type 3 Code 1 (Host Unreachable) atau Code 0 (Network Unreachable)', 'B': 'ICMP Type 8 Code 0', 'C': 'ICMP Type 0 Code 0', 'D': 'ICMP Type 13 (Timestamp)'}, 'A', 'CONTROLLING_VARIABLES', "Jika rute berstatus inactive karena antarmuka keluar mati (flag 'I' / unreachable pada MikroTik), router membuang paket dan mengembalikan pesan ICMP Type 3 Unreachable ke pengirim."), ("Seorang siswa mendapati bahwa setelah mereset kartu jaringannya, ping ke server lab memunculkan DHU selama 3 detik pertama sebelum akhirnya berubah menjadi 'Reply'. Fenomena transisi apakah yang mendasari korelasi waktu ini?", {'A': 'Waktu tunda resolusi ARP dan proses Spanning Tree Protocol (STP) listening/learning pada port switch sebelum memasuki status forwarding', 'B': 'Waktu pemanasan kabel tembaga oleh elektron', 'C': 'Waktu yang dibutuhkan server untuk memeriksa sidik jari siswa', 'D': 'Waktu pendinginan kipas prosesor router'}, 'A', 'CORRELATIONAL_REASONING', 'Port switch yang baru aktif memerlukan waktu negosiasi STP (listening & learning ~15-30 detik jika portfast tidak aktif) dan pengiriman kueri ARP awal, menyebabkan paket awal gagal dengan DHU.'), ("Di sebuah switch Layer 3 Cisco, teknisi telah membuat antarmuka `interface vlan 10` dan `interface vlan 20`. Klien di VLAN 10 dapat ping ke IP gateway-nya sendiri, namun saat ping ke gateway VLAN 20 muncul pesan 'Destination Host Unreachable'. Perintah konfigurasi global apakah yang lupa diaktifkan?", {'A': 'ip routing', 'B': 'no shutdown', 'C': 'switchport mode access', 'D': 'enable secret'}, 'A', 'COMBINATORIAL_REASONING', "Pada switch L3, fungsi routing IP antar-VLAN (Inter-VLAN routing) dinonaktifkan secara default; tanpa perintah global 'ip routing', switch bertindak murni sebagai switch L2 dan menolak merutekan paket antar-VLAN."), ('Pada perancangan pengalamatan VLSM, seorang siswa tidak sengaja memberikan alamat IP 192.168.10.63 dengan subnet mask 255.255.255.224 (/27) ke sebuah komputer server. Mengapa komputer lain di lab gagal menghubunginya dengan galat Destination Host Unreachable?', {'A': 'Karena IP 192.168.10.63 adalah alamat broadcast dari subnet kedua (192.168.10.32/27), sehingga bukan alamat host yang valid dan tidak dapat merespons paket unicast', 'B': 'Karena angka 63 membawa sial pada penomoran jaringan', 'C': 'Karena subnet mask 255.255.255.224 hanya boleh digunakan untuk printer', 'D': 'Karena router memblokir seluruh angka yang berakhiran angka 3'}, 'A', 'PROPORTIONAL_REASONING', 'Perhitungan rentang /27 (ukuran blok 32): Subnet 1: .0 s/d .31 (Broadcast .31); Subnet 2: .32 s/d .63 (Network .32, Broadcast .63). Alamat broadcast tidak boleh dipasang pada antarmuka host.'), ('Pada jaringan skala besar dengan protokol routing dinamis OSPF, pesan galat DHU transient (sementara) dapat muncul selama beberapa ratus milidetik saat terjadi pemutusan kabel utama. Faktor probabilistik jaringan apakah yang memicu fenomena ini?', {'A': 'Waktu tunda konvergensi routing (Routing Convergence Delay) saat algoritma Dijkstra menghitung ulang pohon jalur terpendek (SPF) baru', 'B': 'Perubahan rotasi bumi yang mengganggu GPS router', 'C': 'Penurunan kuota bandwidth satelit secara acak', 'D': 'Penurunan tegangan listrik AC pada stopkontak'}, 'A', 'PROBABILISTIC_REASONING', 'Selama proses flooding LSA dan kalkulasi Shortest Path First (SPF), tabel rute lama telah dihapus namun rute baru belum terpasang; paket yang melintas dalam jendela waktu singkat ini di-drop dengan DHU.')]}

EXTRA_KC_BLUEPRINTS['ICMP_TROUBLE_RTO'] = {'easy': [("Arti dari pesan galat 'Request Timed Out' (RTO) pada keluaran perintah pengujian ping adalah...", {'A': 'Paket Echo Request telah dikirimkan, namun komputer pengirim tidak menerima paket balasan Echo Reply dalam batas waktu tunggu yang ditentukan', 'B': 'Komputer pengirim mengalami kerusakan pada sistem operasi', 'C': 'Kabel jaringan telah kadaluarsa tanggal penggunaannya', 'D': 'Kecepatan internet komputer tujuan melebihi batas kecepatan cahaya'}, 'A', 'CONTROLLING_VARIABLES', 'RTO terjadi saat timer batas tunggu pengirim (default 1000-4000 ms) habis tanpa menerima respons; berbeda dengan DHU, pada RTO tidak ada perangkat yang mengirimkan pesan penolakan aktif (hening).'), ('Penyebab paling umum mengapa komputer Windows di laboratorium sekolah tidak membalas ping dari komputer lain (selalu RTO) padahal aplikasi file sharing berjalan normal adalah...', {'A': 'Windows Defender Firewall secara default memblokir paket masuk ICMPv4 Echo Request (aturan File and Printer Sharing ICMP belum diaktifkan)', 'B': 'Kartu jaringan komputer tujuan kehabisan daya listrik', 'C': 'Komputer tujuan tidak menyukai komputer pengirim', 'D': 'Kabel UTP yang digunakan tidak berwarna biru'}, 'A', 'CONTROLLING_VARIABLES', 'Konfigurasi standar Windows Firewall menyaring dan membuang (drop silent) paket ICMP yang masuk demi alasan keamanan, meskipun layanan data lain (TCP/SMB) diizinkan lewat.'), ("Perbedaan mendasar antara pesan galat 'Destination Host Unreachable' (DHU) dan 'Request Timed Out' (RTO) ditinjau dari interaksi protokol jaringan adalah...", {'A': 'DHU berarti ada perangkat (gateway/klien) yang aktif membalas memberitahukan kegagalan rute, sedangkan RTO berarti hening total tanpa ada balasan sama sekali', 'B': 'DHU hanya terjadi pada Wi-Fi, sedangkan RTO hanya terjadi pada kabel', 'C': 'DHU menandakan internet sangat cepat, sedangkan RTO menandakan internet mati', 'D': 'Tidak ada perbedaan, keduanya memiliki arti yang sama persis'}, 'A', 'COMBINATORIAL_REASONING', 'DHU adalah respon aktif (ICMP Type 3 error generated by a node); RTO adalah kondisi pasif (timeout expired locally at sender because packet was dropped somewhere in transit).'), ('Seorang siswa membawa smartphone ke ujung lapangan sekolah. Saat sinyal Wi-Fi turun ke level ekstrem di bawah -88 dBm, hasil uji ping mulai menunjukkan pesan RTO berselang-seling. Hubungan korelasional fisis apakah yang terjadi?', {'A': 'Korelasi antara penurunan daya terima sinyal di bawah ambang sensitivitas radio (Receiver Sensitivity) dengan lonjakan tingkat kehilangan paket (Packet Loss)', 'B': 'Korelasi antara suhu lapangan rumput dengan frekuensi radio', 'C': 'Korelasi antara warna casing smartphone dengan kecepatan transmisi data', 'D': 'Korelasi antara daya baterai dengan panjang gelombang'}, 'A', 'CORRELATIONAL_REASONING', 'Ketika sinyal jatuh di bawah batas sensitivitas penerima (misal -85 s/d -90 dBm), radio gagal mendemodulasi frame dan CRC error melonjak tajam, memicu frame dibuang dan timbul RTO.'), ('Ketika sebuah kabel patch cord UTP di lab terinjak kursi roda hingga kawat tembaga nomor 1 (Tx+) kadang tersambung dan kadang terputus, pola hasil ping yang paling mungkin terlihat adalah...', {'A': 'Muncul pola intermittent: beberapa paket Reply bergantian acak dengan pesan Request Timed Out (RTO)', 'B': 'Kecepatan internet otomatis meningkat 200%', 'C': 'Alamat IP komputer otomatis berubah menjadi 127.0.0.1', 'D': 'Komputer langsung mengeluarkan asap'}, 'A', 'PROBABILISTIC_REASONING', 'Kontak fisik yang goyah (intermittent) menimbulkan degradasi fisik stokastik: saat kawat terhubung paket berhasil (Reply), saat kawat terputus paket hilang di kabel (RTO).')], 'medium': [("Laptop siswa dapat membuka situs web sekolah (HTTP port 80 / HTTPS port 443) dengan lancar di browser, namun ketika siswa melakukan ping ke alamat IP server web tersebut, hasilnya selalu 'Request Timed Out'. Analisis teknis manakah yang tepat?", {'A': 'Administrator server web memasang aturan firewall untuk membuang paket ICMP (drop ping) demi keamanan, namun tetap mengizinkan port TCP 80 dan 443', 'B': 'Protokol HTTP berjalan tanpa menggunakan jaringan internet', 'C': 'Browser Google Chrome dapat menembus kabel yang putus', 'D': 'Server web tidak memiliki alamat IP'}, 'A', 'CONTROLLING_VARIABLES', 'Banyak server publik mengonfigurasi firewall untuk menolak paket ICMP echo request (stealth mode) demi mereduksi profiling pemindaian peretas, sementara port layanan aplikasi web tetap dibuka normal.'), ("Fenomena 'Asymmetric Routing' dapat memicu pesan galat Request Timed Out pada pengujian ping antarlab karena...", {'A': 'Paket Echo Request berhasil tiba di host tujuan melalui Jalur A, namun paket balasan Echo Reply dikirimkan melewati Jalur B yang memblokir ICMP atau tidak memiliki rute balik', 'B': 'Kabel jaringan dipasang dengan sudut kemiringan 45 derajat', 'C': 'Panjang kabel kirim dan kabel terima tidak sama persis hingga milimeter', 'D': 'Siswa menggunakan tangan kiri saat mengetik perintah ping'}, 'A', 'COMBINATORIAL_REASONING', 'Rute transmisi di internet bersifat connectionless hop-by-hop; jika rute berangkat dan rute pulang berbeda, stateful firewall di jalur pulang akan membuang paket karena tidak mengenali sesi awalnya.'), ('Grafik pemantauan menunjukkan utilisasi CPU pada router gateway sekolah mencapai 100% akibat serangan virus lokal. Mengapa pengujian ping ke router mulai menghasilkan pesan Request Timed Out berselang-seling?', {'A': 'Router memprioritaskan pemrosesan penerusan paket data (fast path) dan membuang paket ICMP yang ditujukan ke prosesor internalnya karena kehabisan antrean memori CPU', 'B': 'Kabel UTP terbakar akibat panas prosesor', 'C': 'Arus listrik AC di laboratorium berubah menjadi arus searah DC', 'D': 'Kapasitas RAM pada laptop penguji otomatis terkuras habis'}, 'A', 'PROPORTIONAL_REASONING', 'Paket ping ke IP router diproses oleh Control Plane (CPU prosesor utama); saat CPU terbebani 100%, router secara proporsional mengorbankan paket manajemen non-kritis (seperti ICMP) untuk bertahan hidup.'), ('Di laboratorium TKJ, setiap kali microwave di ruang guru dinyalakan, uji ping kontinu (`ping -t`) ke Access Point menunjukkan pola: 4 Reply, 6 RTO, 3 Reply, 5 RTO. Hubungan kausalitas apakah yang terbukti?', {'A': 'Kebocoran radiasi gelombang mikro 2.45 GHz menenggelamkan sinyal radio Wi-Fi kanal 6, memicu kegagalan demodulasi frame secara periodik', 'B': 'Microwave menyerap daya listrik komputer siswa', 'C': 'Microwave mengirimkan virus komputer melalui kabel tanah', 'D': 'Access Point sengaja mematikan diri saat mencium aroma makanan'}, 'A', 'CORRELATIONAL_REASONING', 'Interferensi elektromagnetik RF berkorelasi langsung dengan lonjakan frame loss; saat magnetron microwave berosilasi memancarkan energi liar, SNR jatuh ke tingkat negatif yang memicu hilangnya paket data.'), ("Dari pengujian ping kontinu sebanyak 50 paket ke server file, tercatat 10 paket berakhir dengan status 'Request Timed Out'. Berapakah persentase kehilangan paket (packet loss rate) dan status kualitas koneksinya?", {'A': 'Packet Loss = 20% (10/50), kualitas koneksi sangat buruk dan tidak layak untuk aplikasi real-time', 'B': 'Packet Loss = 50%, kualitas koneksi sempurna', 'C': 'Packet Loss = 2%, koneksi normal untuk jaringan LAN', 'D': 'Packet Loss = 0%, tidak ada masalah'}, 'A', 'PROBABILISTIC_REASONING', 'Perhitungan peluang kegagalan empiris: Packet Loss Rate = (Paket Gagal / Total Paket) x 100% = (10 / 50) x 100% = 20%. Kehilangan paket 20% pada jaringan kabel LAN mengindikasikan kerusakan fisik kabel atau tabrakan parah.')], 'hard': [('Pada menu IP Firewall Filter MikroTik, terdapat aturan: Rule 0: `chain=input action=drop` (membuang semua paket masuk), dan Rule 1: `chain=input protocol=icmp action=accept`. Mengapa ping ke router selalu menghasilkan Request Timed Out?', {'A': 'Karena aturan firewall dievaluasi secara berurutan dari atas ke bawah; paket ICMP sudah terlanjur dicocokkan dan dibuang oleh Rule 0 sebelum sempat membaca Rule 1', 'B': 'Karena protokol ICMP tidak didukung oleh sistem operasi RouterOS', 'C': 'Karena port winbox MikroTik belum diubah', 'D': 'Karena kabel LAN MikroTik terpasang di port ether5'}, 'A', 'COMBINATORIAL_REASONING', "Prinsip urutan aturan firewall (Rule Ordering): pemrosesan paket berhenti seketika saat aturan pertama yang cocok dieksekusi; menempatkan 'drop all' di atas aturan izin membuat aturan izin di bawahnya tidak pernah dieksekusi."), ('Ketika siswa melakukan ping ke server cabang melalui jalur VPN / PPPoE dengan perintah `ping -l 1472` hasilnya selalu RTO, namun saat diuji dengan `ping -l 1400` hasilnya Reply lancar. Penyebab mendasar fenomena Black Hole Router ini adalah...', {'A': 'Header enkripsi terowongan VPN menambah overhead ukuran paket melampaui MTU jalur fisik, sementara router perantara membuang paket besar tanpa mengirimkan pesan fragmentasi', 'B': 'Kabel VPN terputus di tengah jalan', 'C': 'Server cabang hanya menerima file berukuran genap', 'D': 'Angka 1472 dilarang oleh protokol kriptografi'}, 'A', 'CORRELATIONAL_REASONING', 'Overhead terowongan (IPsec/GRE/PPPoE) memangkas MTU efektif (misal menjadi 1400-1450 byte); jika opsi DF-bit aktif dan router perantara memblokir pesan ICMP Type 3 Code 4 (Fragmentation Needed), paket besar dibuang diam-diam (black hole).'), ("Teknisi jaringan menjalankan perangkat lunak penganalisis paket (Wireshark) pada laptop penguji. Terlihat frame 'Echo Request' keluar dari kartu jaringan, namun tidak pernah ada frame 'Echo Reply' yang masuk. Kesimpulan investigasi kontrol yang valid adalah...", {'A': 'Masalah berada di luar kartu jaringan penguji (bisa berupa kabel putus, firewall host tujuan membuang paket, atau host tujuan mati)', 'B': 'Kartu jaringan laptop penguji rusak total dan harus diganti baru', 'C': 'Sistem operasi laptop penguji tidak memiliki driver TCP/IP', 'D': 'Monitor laptop penguji mengalami kerusakan piksel'}, 'A', 'CONTROLLING_VARIABLES', 'Bukti frame keluar memastikan stack pengirim bekerja normal; ketiadaan respon membatasi wilayah investigasi pada media transmisi, konfigurasi rute, dan kebijakan keamanan di host tujuan.'), ('Pada tautan internet satelit geostasioner (GEO) di daerah terpencil, jarak orbit 36.000 km menimbulkan waktu tempuh rambat cahaya bolak-balik minimal ~540 ms. Jika utilitas ping sistem operasi disetel dengan timeout default 500 ms (`ping -w 500`), apa yang akan terjadi?', {'A': "Seluruh hasil ping akan salah dilaporkan sebagai 'Request Timed Out' meskipun paket sebenarnya berhasil sampai dan dibalas oleh server tujuan", 'B': 'Satelit akan jatuh dari orbitnya', 'C': 'Kecepatan rambat cahaya akan bertambah cepat secara otomatis', 'D': 'Kabel modem satelit akan putus'}, 'A', 'PROPORTIONAL_REASONING', 'Latensi propagasi fisik: $2 \\times (36.000\\text{ km} / 300.000\\text{ km/s}) \\times 2 \\approx 480-600\\text{ ms}$. Jika batas timeout lokal (500 ms) lebih kecil daripada waktu rambat fisis minimal, pengirim menganggap paket timeout sebelum paket balasan tiba.'), ('Serangan SYN Flood DoS yang membanjiri server web sekolah dengan jutaan paket inisiasi koneksi palsu menyebabkan tabel memori koneksi (Connection Tracking Table / conntrack) penuh. Mengapa pengujian ping ke server tersebut ikut terdampak menghasilkan RTO?', {'A': 'Karena firewall/kernel kehabisan alokasi memori buffer untuk mencatat dan memproses paket baru yang masuk, sehingga paket ICMP ikut terbuang di antrean kartu jaringan', 'B': 'Karena virus memakan kawat tembaga kabel', 'C': 'Karena alamat MAC server berubah menjadi alamat IP', 'D': 'Karena keyboard server terkunci otomatis'}, 'A', 'PROBABILISTIC_REASONING', 'Tabel conntrack yang meluap (conntrack table full) menyebabkan kernel sistem operasi membuang seluruh paket baru tanpa pandang bulu di antrean network driver (packet ring buffer overflow), memicu 100% RTO.')]}

